			if ( 'database' === $schema_type ) {
				$database_name          = $this->get_mysql_show_database_name( $tokens, $position, $unsupported_message );
				$parsed_query['schema'] = $this->get_mysql_show_database_backend_schema( $database_name, substr( $unsupported_message, strlen( 'Unsupported ' ), -strlen( ' statement.' ) ) );
			} else {
				$schema_name    = $this->get_mysql_show_optional_schema_name( $tokens, $position, $unsupported_message );
				$backend_schema = $this->get_mysql_read_table_backend_schema( $schema_name );
				if ( $this->is_postgresql_internal_schema( $backend_schema ) ) {
					throw new InvalidArgumentException( $unsupported_message );
