			if ( null !== $translated_query ) {
				return $translated_query;
			}
		}
		return null;
	}
	private function execute_mysql_admin_statements( array $statements, bool $clear_metadata_caches ): int {
		$this->execute_postgresql_statements( $statements );
		if ( $clear_metadata_caches ) {
			$this->clear_mysql_metadata_caches();
		}
		$this->last_result = 0;
		return $this->last_result;
	}
	private function execute_mysql_translated_create_table_query( array $create_table_query ): int {
		if ( ! empty( $create_table_query['noop'] ) ) {
			return $this->execute_mysql_admin_noop_query();
		}

		$metadata_query  = $create_table_query['metadata_query'] ?? null;
		$metadata_tables = null === $metadata_query
			? array()
			: $this->get_postgresql_catalog_mysql_schema_metadata_or_fail( $metadata_query );
		$result          = $this->execute_postgresql_statements(
			$this->prepend_postgresql_mysql_helper_type_statements(
				$create_table_query['statements'],
				$metadata_query,
				null !== $metadata_query
			)
		);
		$metadata_schema = ! empty( $create_table_query['temporary'] )
			? $this->get_temporary_schema_for_metadata_table( $create_table_query['table'] )
			: $create_table_query['schema'];

		if ( null !== $metadata_query ) {
			$this->sync_mysql_schema_catalog_side_effects_for_schema(
				$metadata_tables,
				! empty( $create_table_query['temporary'] ) ? array( $this, 'get_temporary_schema_for_metadata_table' ) : $metadata_schema
			);
			return $result;
		}

		$this->clear_mysql_metadata_caches();
		if ( '' !== ( $create_table_query['table_comment'] ?? '' ) ) {
			$this->sync_postgresql_catalog_table_comment( $metadata_schema, $create_table_query['table'], $create_table_query['table_comment'] );
		}
		return $result;
	}
	private function get_unsupported_mysql_administration_statement_message( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return null;
		}

		$message = $this->get_mysql_unsupported_statement_message( 'administration', $tokens[0]->id );
		if ( null !== $message ) {
			return $message;
		}

		if ( WP_MySQL_Lexer::ALTER_SYMBOL === $tokens[0]->id ) {
			return $this->get_mysql_unsupported_statement_message( 'alter', $tokens[1]->id ?? null );
		}

		return WP_MySQL_Lexer::RENAME_SYMBOL === $tokens[0]->id && WP_MySQL_Lexer::USER_SYMBOL === ( $tokens[1]->id ?? null )
			? 'Unsupported RENAME USER statement.'
			: null;
