	private function execute_mysql_catalog_show_result( string $sql, array $params, ?array $where_filter, array $filter_columns, string $filter_prefix, string $order_by_sql, ?string $cache_key, string $unsupported_message, $fetch_mode, ...$fetch_mode_args ) {
		if ( $this->load_mysql_introspection_result_from_cache( $cache_key ) ) {
			return $this->last_result;
		}

		$where_expression_filter = $this->is_mysql_show_where_expression_filter( $where_filter ) ? $where_filter : null;
		$pushdown_conditions     = $where_expression_filter['pushdown_conditions'] ?? array();
		if ( ! empty( $pushdown_conditions ) ) {
			$conditions = array();
			foreach ( $pushdown_conditions as $filter ) {
				if ( ! isset( $filter_columns[ $filter['column'] ] ) ) {
					throw new InvalidArgumentException( $unsupported_message );
				}

				$conditions[] = sprintf(
					'like' === ( $filter['operator'] ?? '=' ) ? '%s LIKE ? ESCAPE ' . $this->get_mysql_like_default_escape_sql() : '%s = ?',
					$filter_columns[ $filter['column'] ]
				);
				$params[]     = $filter['value'];
			}

			$sql                    .= "\n" . $filter_prefix . implode( ' AND ', $conditions );
			$where_expression_filter = null;
		}

		$sql .= "\n" . $order_by_sql;
		$stmt = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);
		$this->last_column_meta          = $this->normalize_column_meta( $stmt );
		if ( null !== $where_expression_filter ) {
			$rows = $stmt->fetchAll( PDO::FETCH_ASSOC );
			$rows = $this->filter_mysql_static_show_rows( $rows, $where_expression_filter );
			$this->set_mysql_associative_result_rows( $rows, $fetch_mode, ...$fetch_mode_args );
		} else {
			$this->last_result     = $stmt->fetchAll( $fetch_mode, ...$fetch_mode_args );
			$this->last_found_rows = count( $this->last_result );
		}

		$this->store_mysql_introspection_result_in_cache( $cache_key );
		return $this->last_result;
	}
	private function execute_mysql_catalog_projected_show_result( array $descriptor, $fetch_mode, ...$fetch_mode_args ) {
		$sql = $this->get_mysql_catalog_projected_show_sql(
			$descriptor,
			$params,
			! empty( $descriptor['filter_in_php'] )
		);

		if ( ! empty( $descriptor['filter_in_php'] ) ) {
			return $this->execute_mysql_filtered_static_show_result(
				$descriptor['columns'],
				$this->get_mysql_show_query_rows( $sql, $params ),
				$descriptor['filter'] ?? null,
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		return $this->execute_mysql_catalog_show_result(
			$sql,
			$params,
			$descriptor['filter'] ?? null,
			$this->get_direct_information_schema_native_projection_expression_map( $descriptor['filter_columns'] ?? $descriptor['expressions'] ),
			$descriptor['filter_prefix'] ?? 'AND ',
			$descriptor['order_by'],
			$descriptor['cache_key'] ?? null,
			$descriptor['unsupported_message'] ?? 'Unsupported SHOW statement.',
			$fetch_mode,
			...$fetch_mode_args
		);
	}
	private function get_mysql_catalog_projected_show_descriptor( array $columns, $expressions, string $from, ?string $where = null, array $params = array(), string $order_by = '', array $extra = array() ): array {
		return array_merge( compact( 'columns', 'expressions', 'from', 'where', 'params', 'order_by' ), $extra );
	}
	private function get_mysql_catalog_projected_show_rows( array $descriptor ): array {
		$sql = $this->get_mysql_catalog_projected_show_sql( $descriptor, $params, true );
		return $this->get_mysql_show_query_rows( $sql, $params );
	}
	private function get_mysql_catalog_projected_show_sql( array $descriptor, ?array &$params, bool $include_order_by ): string {
		$params = $descriptor['params'] ?? array();
		$sql    = 'SELECT
' . $this->get_mysql_show_projection_sql(
			$descriptor['columns'],
			$this->get_direct_information_schema_native_projection_expression_map( $descriptor['expressions'] ),
			$descriptor['indent'] ?? "\t"
		) . '
FROM ' . $descriptor['from'];

		if ( ! empty( $descriptor['where'] ) ) {
			$sql .= "\nWHERE " . $descriptor['where'];
		}

		if ( null !== ( $descriptor['like'] ?? null ) ) {
			$sql     .= "\n" . ( empty( $descriptor['where'] ) ? 'WHERE ' : 'AND ' ) . $descriptor['like_expression'] . ' LIKE ? ESCAPE ' . $this->get_mysql_like_default_escape_sql();
			$params[] = $descriptor['like'];
		}

		if ( $include_order_by && ! empty( $descriptor['order_by'] ) ) {
			$sql .= "\n" . $descriptor['order_by'];
		}
		return $sql;
	}
	private function execute_mysql_use_statement( string $database_name ): int {
		if (
			0 === strcasecmp( $database_name, $this->main_db_name )
			|| 0 === strcasecmp( $database_name, 'public' )
		) {
			return $this->execute_mysql_use_statement_success( $this->main_db_name );
		}

		if ( 0 === strcasecmp( $database_name, 'information_schema' ) ) {
			return $this->execute_mysql_use_statement_success( 'information_schema' );
		}

		if (
			$this->should_use_postgresql_catalog_metadata()
			&& ! $this->is_postgresql_internal_schema( $database_name )
			&& $this->mysql_database_exists_in_postgresql_catalog( $database_name )
		) {
			return $this->execute_mysql_use_statement_success( $database_name );
		}
		throw new InvalidArgumentException( 'Unsupported USE statement.' );
	}
	private function execute_mysql_use_statement_success( string $database_name ): int {
		$this->db_name = $database_name;
		$this->clear_mysql_metadata_caches();
		$this->last_result = 0;
		return $this->last_result;
	}
	private function execute_show_tables_query( bool $is_full, string $schema_name, string $database_name, ?string $like, ?array $where_filter, $fetch_mode, ...$fetch_mode_args ) {
		$columns      = $this->get_show_tables_output_columns( $database_name, $is_full );
		$table_column = $columns[0];
		if ( 0 === strcasecmp( $database_name, 'information_schema' ) ) {
			return $this->execute_mysql_information_schema_relation_name_show_result(
				$columns,
				$table_column,
				$is_full ? array( 'Table_type' => 'SYSTEM VIEW' ) : array(),
				$like,
				$where_filter,
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		return $this->execute_mysql_catalog_projected_show_result( $this->get_mysql_catalog_projected_show_statement_descriptor( 'tables', compact( 'is_full', 'schema_name', 'database_name', 'like', 'where_filter' ) ), $fetch_mode, ...$fetch_mode_args );
	}
	private function get_mysql_like_default_escape_sql(): string {
		return $this->connection->quote( '\\' );
	}
	private function execute_show_table_status_query( array $show_table_status_query, $fetch_mode, ...$fetch_mode_args ) {
		$columns = $this->get_mysql_show_output_columns( 'table_status' );
		if ( 0 === strcasecmp( $show_table_status_query['database'], 'information_schema' ) ) {
			return $this->execute_mysql_information_schema_relation_name_show_result(
				$columns,
				'Name',
				array(
					'Create_options' => '',
					'Comment'        => 'SYSTEM VIEW',
				),
				null,
				$show_table_status_query['filter'],
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		return $this->execute_mysql_catalog_projected_show_result( $this->get_mysql_catalog_projected_show_statement_descriptor( 'table_status', compact( 'show_table_status_query' ) ), $fetch_mode, ...$fetch_mode_args );
	}
	private function execute_mysql_information_schema_relation_name_show_result( array $columns, string $name_column, array $values, ?string $like, ?array $where_filter, $fetch_mode, ...$fetch_mode_args ) {
		$rows = $this->get_mysql_information_schema_relation_name_rows( $columns, $name_column, $values );
		return $this->execute_mysql_static_show_result_with_filters( $columns, $rows, $this->get_mysql_show_like_filter( $name_column, $like ), $where_filter, $fetch_mode, ...$fetch_mode_args );
	}
	private function get_mysql_information_schema_relation_name_rows( array $columns, string $name_column, array $values = array() ): array {
		$rows = array();
		foreach ( $this->get_direct_information_schema_relation_names() as $relation ) {
			$rows[] = array_merge( array_fill_keys( $columns, null ), array( $name_column => strtoupper( $relation ) ), $values );
		}
		return $rows;
	}
	private function execute_show_create_table_query( array $show_create_table_query, $fetch_mode, ...$fetch_mode_args ) {
		$table_name      = $show_create_table_query['table'];
		$resolved_schema = $this->resolve_mysql_table_schema_for_introspection(
			$show_create_table_query['schema'],
			$table_name
		);
		if ( 0 === strcasecmp( $resolved_schema, 'information_schema' ) ) {
			$descriptors = $this->get_direct_information_schema_column_descriptors( $table_name );
			if ( null === $descriptors ) {
				return $this->set_mysql_static_show_result( array( 'Table', 'Create Table' ), array(), $fetch_mode, ...$fetch_mode_args );
			}
			$rows = array(
				array(
					'Table'        => $table_name,
					'Create Table' => sprintf(
						"CREATE TEMPORARY TABLE %s (\n%s\n) ENGINE=MEMORY DEFAULT CHARSET=%s COLLATE=%s",
						$this->quote_mysql_identifier( strtolower( $table_name ) ),
						implode( ",\n", array_column( $descriptors, 'definition' ) ),
						self::DEFAULT_MYSQL_CHARSET,
						self::DEFAULT_MYSQL_COLLATION
					),
				),
			);
			return $this->set_mysql_static_show_result( array( 'Table', 'Create Table' ), $rows, $fetch_mode, ...$fetch_mode_args );
		}
		$cache_key = $this->get_mysql_introspection_result_cache_key(
			'show_create_table',
			$fetch_mode,
			array( $resolved_schema, $table_name, $fetch_mode, $fetch_mode_args )
		);
		if ( $this->load_mysql_introspection_result_from_cache( $cache_key ) ) {
			return $this->last_result;
		}

		$metadata = $this->get_show_create_table_metadata( $resolved_schema, $table_name );
		$columns  = $metadata['columns'];
		if ( empty( $columns ) ) {
			return $this->set_mysql_static_show_result( array( 'Table', 'Create Table' ), array(), $fetch_mode, ...$fetch_mode_args );
		}
		$create_statement = $this->get_mysql_create_table_statement_from_metadata(
			$table_name,
			$columns,
			$metadata['indexes'],
			$metadata['foreign_keys'],
			$metadata['checks'],
			$metadata['table']['comment'],
			$this->is_mysql_temporary_schema_name( $resolved_schema ),
			$metadata['table']['collation']
		);
		$rows             = array(
			array(
				'Table'        => $table_name,
				'Create Table' => $create_statement,
			),
		);
		$result           = $this->set_mysql_static_show_result( array( 'Table', 'Create Table' ), $rows, $fetch_mode, ...$fetch_mode_args );
		$this->store_mysql_introspection_result_in_cache( $cache_key );
		return $result;
	}
	private function get_show_create_table_metadata( string $schema_name, string $table_name, bool $log_queries = true, bool $include_foreign_keys = true ): array {
		$logged_queries = $this->last_postgresql_queries;
		try {
			return $this->get_mysql_key_value_array( 'columns', $this->get_show_create_table_metadata_rows( 'columns', $schema_name, $table_name, $log_queries ), 'indexes', $this->get_show_create_table_metadata_rows( 'indexes', $schema_name, $table_name, $log_queries ), 'foreign_keys', $include_foreign_keys ? $this->get_show_create_table_metadata_rows( 'foreign_keys', $schema_name, $table_name, $log_queries ) : array(), 'checks', $this->get_show_create_table_metadata_rows( 'checks', $schema_name, $table_name, $log_queries ), 'table', $this->get_show_create_table_table_metadata( $schema_name, $table_name, $log_queries ) );
		} finally {
			if ( ! $log_queries ) {
				$this->last_postgresql_queries = $logged_queries;
			}
		}
	}
	private function get_postgresql_prefix_index_expression_column_name_sql( string $expression_sql ): string {
		return sprintf(
