		return $this->get_mysql_create_table_sql( $table_name, $definitions, $columns, $table_comment, $temporary, $table_collation );
	}
	private function get_mysql_create_table_column_definition( array $column ): string {
		$extra      = (string) ( $column['extra'] ?? '' );
		$definition = sprintf( '  %s %s', $this->quote_mysql_identifier( (string) $column['column_name'] ), (string) $column['column_type'] );
		if ( 'NO' === strtoupper( (string) $column['is_nullable'] ) ) {
			$definition .= ' NOT NULL';
		}
		if ( 1 === preg_match( '/auto_increment/i', $extra ) ) {
			$definition .= ' AUTO_INCREMENT';
		}
		$default     = $column['column_default'] ?? null;
		$definition .= null === $default ? ( 'NO' !== strtoupper( (string) $column['is_nullable'] ) ? ' DEFAULT NULL' : '' ) : ( $this->is_mysql_current_timestamp_default_metadata( (string) $default ) ? ' DEFAULT ' . (string) $default : ( $this->mysql_column_extra_has_default_generated( $extra ) ? ' DEFAULT (' . (string) $default . ')' : ' DEFAULT ' . $this->quote_mysql_utf8_string_literal( (string) $default ) ) );
		if ( true === $this->mysql_column_extra_has_on_update_current_timestamp( $extra ) ) {
			$definition .= ' ON UPDATE CURRENT_TIMESTAMP';
		}
