			$key_parts[] = $this->quote_mysql_identifier( (string) $column['column_name'] ) . ( null !== ( $column['sub_part'] ?? null ) ? sprintf( '(%d)', (int) $column['sub_part'] ) : '' ) . ( 'D' === strtoupper( (string) ( $column['collation'] ?? '' ) ) ? ' DESC' : '' );
