	}
	private function get_mysql_create_table_identifier_list( array $rows, string $column ): string {
		return implode( ', ', array_map( array( $this, 'quote_mysql_identifier' ), array_map( 'strval', array_column( $rows, $column ) ) ) );
	}
	private function get_mysql_create_table_check_definition( array $check ): string {
