	private function get_mysql_create_table_sql( string $table_name, array $definitions, array $columns, string $table_comment, bool $temporary, ?string $table_collation ): string {
		$collation = (string) ( null !== $table_collation && '' !== $table_collation ? $table_collation : ( array_values( array_filter( array_column( $columns, 'collation_name' ) ) )[0] ?? $this->collation ) );
