			$descriptor['columns'],
			$descriptor['rows'],
			$descriptor['filter'] ?? null,
			$fetch_mode,
			...$fetch_mode_args
		);
		if ( ! empty( $descriptor['reset_found_rows'] ) ) {
			$this->last_found_rows = 0;
		}
