			array( 'is_mysql_intrinsically_valid_temporal_text_expression', false ),
			array( 'is_mysql_intrinsically_valid_temporal_wrapper_expression', false ),
			array( 'is_mysql_date_function_with_temporal_source', false ),
			array( 'get_mysql_intrinsically_valid_temporal_cast_expression_bounds', true ),
			array( 'get_mysql_intrinsically_valid_from_unixtime_timestamp_sql', true ),
			array( 'is_mysql_null_from_unixtime_expression', false ),
			array( 'get_mysql_intrinsically_valid_formatted_from_unixtime_expression_format', true ),
			array( 'is_mysql_null_date_format_expression', false ),
			array( 'get_mysql_intrinsically_valid_date_format_expression_format', true ),
			array( 'is_mysql_intrinsically_valid_temporal_case_expression', false ),
