		return sprintf(
			'CASE WHEN %1$s ~ %2$s THEN %1$s || %3$s ELSE %1$s END',
			$value_text_sql,
			$this->connection->quote( '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' ),
			$this->connection->quote( ' 00:00:00' )
