			}

			$column_key = strtolower( $column_name );
			if ( isset( $seen[ $column_key ] ) ) {
				return null;
			}

			$columns[]           = $column_name;
			$seen[ $column_key ] = true;
		}
		return count( $columns ) > 0 ? $columns : null;
	}
	private function get_mysql_dml_column_metadata( string $table_name ): array {
		$table_schema = $this->get_mysql_unqualified_dml_table_backend_schema( $table_name );
		return $this->get_mysql_table_catalog_column_metadata_rows( $table_schema, $table_name );
	}
	private function get_mysql_unqualified_dml_table_backend_schema( string $table_name ): string {
		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		if ( 'public' !== $table_schema ) {
			return $table_schema;
		}

		if (
			$this->should_use_postgresql_catalog_metadata()
			&& 0 !== strcasecmp( $this->db_name, $this->main_db_name )
			&& 0 !== strcasecmp( $this->db_name, 'public' )
			&& 0 !== strcasecmp( $this->db_name, 'information_schema' )
			&& ! $this->is_postgresql_internal_schema( $this->db_name )
		) {
			return $this->db_name;
		}
		return $table_schema;
	}
	private function get_postgresql_unqualified_dml_table_reference_sql( string $table_name ): string {
		return $this->get_postgresql_table_identifier_sql(
			$this->get_mysql_unqualified_dml_table_backend_schema( $table_name ),
			$table_name
		);
	}
	private function get_postgresql_table_identifier_sql( string $table_schema, string $table_name ): string {
		if ( 'public' !== $table_schema ) {
			return $this->get_postgresql_schema_identifier( $table_schema, $table_name );
		}
		return $this->connection->quote_identifier( $table_name );
	}
	private function get_non_strict_dml_default_sql_for_column( array $column_metadata ): ?string {
		if ( 'NO' !== strtoupper( (string) ( $column_metadata['is_nullable'] ?? '' ) ) ) {
			return null;
		}

		if ( $this->is_mysql_auto_increment_column_metadata( $column_metadata ) ) {
			return null;
		}

		$default_sql = $this->get_mysql_dml_default_sql_from_metadata( $column_metadata );
		if ( null !== $default_sql ) {
			return $default_sql;
		}
		return $this->get_mysql_implicit_dml_default_sql( (string) ( $column_metadata['column_type'] ?? '' ) );
	}
	private function get_mysql_dml_default_sql_from_metadata( array $column_metadata ): ?string {
		if ( null === ( $column_metadata['column_default'] ?? null ) ) {
			return null;
		}

		$default = (string) $column_metadata['column_default'];
		if (
			$this->is_mysql_current_timestamp_default_metadata( $default )
			|| $this->mysql_column_extra_has_default_generated( (string) ( $column_metadata['extra'] ?? '' ) )
		) {
			$translated_default = $this->translate_mysql_default_fragment( $default );
			if ( null !== $translated_default ) {
				return $translated_default['sql'];
			}
		}
		return $this->connection->quote( $default );
	}
	private function is_mysql_auto_increment_column_metadata( array $column_metadata ): bool {
		return 'auto_increment' === strtolower( (string) ( $column_metadata['extra'] ?? '' ) );
	}
	private function get_mysql_implicit_dml_default_sql( string $column_type ): ?string {
		$base_type = $this->get_base_mysql_dml_column_type( $column_type );

		if ( in_array( $base_type, self::MYSQL_IMPLICIT_DML_EMPTY_STRING_DEFAULT_BASE_TYPES, true ) ) {
			return $this->connection->quote( '' );
		}

		if ( in_array( $base_type, self::MYSQL_IMPLICIT_DML_ZERO_DEFAULT_BASE_TYPES, true ) ) {
			return '0';
		}

		if ( 'date' === $base_type ) {
			return $this->connection->quote( '0000-00-00' );
		}

		if ( 'datetime' === $base_type || 'timestamp' === $base_type ) {
			return $this->connection->quote( '0000-00-00 00:00:00' );
		}

		if ( 'time' === $base_type ) {
			return $this->connection->quote( '00:00:00' );
		}

		if ( 'year' === $base_type ) {
			return $this->connection->quote( '0000' );
		}
		return null;
	}
	private function get_base_mysql_dml_column_type( string $column_type ): string {
		$column_type = strtolower( trim( $column_type ) );
		$type_end    = strlen( $column_type );

		$length_position = strpos( $column_type, '(' );
		if ( false !== $length_position ) {
			$type_end = min( $type_end, $length_position );
		}

		$space_position = strpos( $column_type, ' ' );
		if ( false !== $space_position ) {
			$type_end = min( $type_end, $space_position );
		}
		return substr( $column_type, 0, $type_end );
	}
	private function get_mysql_column_type_display_width( string $column_type ): ?int {
		if ( 1 !== preg_match( '/\(([0-9]+)\)/', $column_type, $matches ) ) {
			return null;
		}
		return (int) $matches[1];
	}
	private function is_mysql_null_token_sequence( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::NULL_SYMBOL === $tokens[ $start ]->id;
	}
	private function is_mysql_strict_sql_mode_active(): bool {
		return $this->is_sql_mode_active( 'STRICT_TRANS_TABLES' )
			|| $this->is_sql_mode_active( 'STRICT_ALL_TABLES' );
	}
	private function get_mysql_top_level_select_parts( string $query, int $statement_start = 1 ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, $statement_start );
		return null === $statement_end ? null : array(
			'tokens'        => $tokens,
			'statement_end' => $statement_end,
		);
	}
	private function translate_mysql_last_insert_id_assignment_select_query( string $query ): ?array {
		$select = $this->get_mysql_top_level_select_parts( $query );
		if ( null === $select ) {
			return null;
		}

		$tokens        = $select['tokens'];
		$statement_end = $select['statement_end'];
		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				1,
				$statement_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::FROM_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::JOIN_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
					WP_MySQL_Lexer::WHERE_SYMBOL,
				)
			)
		) {
			return null;
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, 1, $statement_end );
		if ( null === $projection_ranges ) {
			return null;
		}

		$has_assignment = false;
		foreach ( $projection_ranges as $projection_range ) {
			$expression_bounds = $this->get_mysql_select_projection_expression_bounds(
				$tokens,
				$projection_range['start'],
				$projection_range['end']
			);
			if ( null === $expression_bounds ) {
				return null;
			}

			$assignment_value = $this->get_mysql_last_insert_id_assignment_literal_value(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end']
			);
			if ( null !== $assignment_value ) {
				$has_assignment = true;
				continue;
			}

			for ( $position = $expression_bounds['start']; $position < $expression_bounds['end']; $position++ ) {
				$bounds = $this->get_mysql_common_function_bounds( $tokens, $position, $expression_bounds['end'] );
				if ( null === $bounds || 'last_insert_id' !== $bounds['function'] ) {
					continue;
				}

				$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
				if ( null === $arguments || 0 !== count( $arguments ) ) {
					return null;
				}
			}
		}

		if ( ! $has_assignment ) {
			return null;
		}

		$previous_translation_enabled = $this->mysql_last_insert_id_assignment_translation_enabled;
		$previous_assignment_value    = $this->mysql_last_insert_id_assignment_value;

		$this->mysql_last_insert_id_assignment_translation_enabled = true;
		$this->mysql_last_insert_id_assignment_value               = null;

		try {
			$sql            = $this->translate_mysql_token_sequence_to_postgresql( $tokens, 0, $statement_end );
			$last_insert_id = $this->mysql_last_insert_id_assignment_value;
		} finally {
			$this->mysql_last_insert_id_assignment_translation_enabled = $previous_translation_enabled;
			$this->mysql_last_insert_id_assignment_value               = $previous_assignment_value;
		}

		if ( null === $last_insert_id ) {
			return null;
		}
		return array(
			'sql'            => $sql,
			'last_insert_id' => $last_insert_id,
		);
	}
	private function get_mysql_last_insert_id_assignment_literal_value( array $tokens, int $start, int $end ): ?int {
		$normalized = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start      = $normalized['start'];
		$end        = $normalized['end'];

		$argument = $this->get_mysql_last_insert_id_argument_range( $tokens, $start, $end );
		if ( null === $argument ) {
			return null;
		}

		$literal_start = $argument['start'];
		$literal_end   = $argument['end'];
		if ( $literal_start + 2 === $literal_end && WP_MySQL_Lexer::PLUS_OPERATOR === ( $tokens[ $literal_start ]->id ?? null ) ) {
			++$literal_start;
		}

		if (
			$literal_start + 1 !== $literal_end
			|| ! isset( $tokens[ $literal_start ] )
			|| ! $this->is_mysql_unsigned_integer_token( $tokens[ $literal_start ] )
		) {
			return null;
		}

		$value = $tokens[ $literal_start ]->get_value();
		if ( '' === $value || ! ctype_digit( $value ) ) {
			return null;
		}

		$value = ltrim( $value, '0' );
		if ( '' === $value ) {
			return 0;
		}

		$max = (string) PHP_INT_MAX;
		if ( strlen( $value ) > strlen( $max ) || ( strlen( $value ) === strlen( $max ) && strcmp( $value, $max ) > 0 ) ) {
			return null;
		}
		return (int) $value;
	}
	private function get_mysql_last_insert_id_argument_range( array $tokens, int $start, int $end ): ?array {
		$bounds = $this->get_mysql_common_function_bounds( $tokens, $start, $end );
		if (
			null === $bounds
			|| 'last_insert_id' !== $bounds['function']
			|| $bounds['close'] + 1 !== $end
		) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		return null !== $arguments && 1 === count( $arguments ) ? $arguments[0] : null;
	}
	private function translate_mysql_version_function_select_query( string $query ): ?string {
		$select = $this->get_mysql_top_level_select_parts( $query );
		if ( null === $select ) {
			return null;
		}

		$tokens            = $select['tokens'];
		$statement_end     = $select['statement_end'];
		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, 1, $statement_end );
		if ( null === $projection_ranges || 1 !== count( $projection_ranges ) ) {
			return null;
		}

		$projection = $projection_ranges[0];
		$bounds     = $this->get_mysql_common_function_bounds( $tokens, $projection['start'], $projection['end'] );
		if (
			null === $bounds
			|| 'version' !== $bounds['function']
			|| $bounds['close'] + 1 !== $projection['end']
		) {
			return null;
		}
		return sprintf(
			'SELECT %s AS %s',
			$this->connection->quote( $this->get_mysql_version_string() ),
			$this->connection->quote_identifier( 'VERSION()' )
		);
	}
	private function translate_simple_mysql_select_query( string $query ): ?string {
		$select = $this->get_mysql_top_level_select_parts( $query );
		if ( null === $select ) {
			return null;
		}

		$context = $this->get_simple_mysql_single_table_select_context( $select['tokens'], $select['statement_end'] );
		if ( null === $context ) {
			return null;
		}
		return $this->build_simple_mysql_single_table_select_sql( $select['tokens'], $context );
	}
	private function get_simple_mysql_single_table_select_context(
		array $tokens,
		int $statement_end,
		bool $skip_where_validation = false,
		bool $reject_direct_information_schema_source = false
	): ?array {
		if ( $this->contains_top_level_mysql_token( $tokens, 1, $statement_end, self::MYSQL_SIMPLE_SELECT_UNSUPPORTED_TOKENS ) ) {
			return null;
		}

		$select_end     = $statement_end;
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 1, $statement_end );
		if ( null !== $limit_position ) {
			if ( ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
				return null;
			}

			$select_end = $limit_position;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $select_end );
		if (
			null === $from_position
			|| 1 === $from_position
			|| ! $this->is_supported_simple_select_projection( $tokens, 1, $from_position )
		) {
			return null;
		}

		$source_end = $this->find_first_top_level_mysql_token(
			$tokens,
			array( WP_MySQL_Lexer::ORDER_SYMBOL, WP_MySQL_Lexer::WHERE_SYMBOL ),
			$from_position + 1,
			$select_end
		) ?? $select_end;
		if (
			$reject_direct_information_schema_source
			&& $this->direct_information_schema_source_range_references_information_schema( $tokens, $from_position + 1, $source_end )
		) {
			return null;
		}

		$table_reference_start = $from_position + 1;
		$table_name_end        = $table_reference_start;
		$table_name_for_sql    = $this->parse_mysql_main_database_table_name( $tokens, $table_name_end );
		$position              = $table_reference_start;
		$table_reference       = $this->parse_mysql_main_database_table_reference( $tokens, $position, $source_end );
		if (
			null === $table_name_for_sql
			|| null === $table_reference
			|| $table_name_for_sql !== $table_reference['table']
			|| $position !== $source_end
		) {
			return null;
		}

		$where_position = null;
		$where_end      = null;
		$order_position = null;
		if ( $position < $select_end && WP_MySQL_Lexer::WHERE_SYMBOL === $tokens[ $position ]->id ) {
			$where_position = $position;
			$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $position + 1, $select_end );
			$where_end      = $order_position ?? $select_end;
			if (
				! $skip_where_validation
				&& (
					$where_position + 1 >= $where_end
					|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
				)
			) {
				return null;
			}

			$position = $where_end;
		}

		if ( $position < $select_end && WP_MySQL_Lexer::ORDER_SYMBOL === $tokens[ $position ]->id ) {
			$order_position = $position;
			if ( ! $this->is_supported_simple_select_order_by_clause( $tokens, $order_position, $select_end ) ) {
				return null;
			}

			$position = $select_end;
		}

		if ( $position !== $select_end ) {
			return null;
		}

		$table_reference_sql = $this->get_mysql_main_database_table_reference_sql(
			$tokens,
			$table_reference_start,
			$table_name_end
		);
		if ( null !== $table_reference['alias'] ) {
			$table_reference_sql .= ' AS ' . $this->connection->quote_identifier( $table_reference['alias'] );
		}

		return array(
			'from_position'       => $from_position,
			'limit_position'      => $limit_position,
			'order_position'      => $order_position,
			'select_end'          => $select_end,
			'statement_end'       => $statement_end,
			'table_alias'         => $table_reference['alias'],
			'table_name'          => $table_reference['table'],
			'table_reference_sql' => $table_reference_sql,
			'where_end'           => $where_end,
			'where_position'      => $where_position,
		);
	}
	private function build_simple_mysql_single_table_select_sql(
		array $tokens,
		array $context,
		array $where_replacements = array(),
		bool $include_wordpress_order_tiebreakers = true
	): string {
		$sql = sprintf(
			'SELECT %s FROM %s',
			$this->translate_simple_select_projection_to_postgresql( $tokens, 1, $context['from_position'] ),
			$context['table_reference_sql']
		);

		$scope = $this->get_mysql_single_table_scope( $context['table_name'], $context['table_alias'] );
		if ( null !== $context['where_position'] ) {
			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$context['where_position'] + 1,
				$context['where_end'],
				$scope,
				$where_replacements
			);
			$sql      .= ' WHERE ' . $where_sql['sql'];
		}

		if ( null !== $context['order_position'] ) {
			$order_sql = $this->translate_mysql_order_by_token_sequence_to_postgresql(
				$tokens,
				$context['order_position'] + 2,
				$context['select_end'],
				$scope,
				false
			);
			$sql      .= ' ORDER BY ' . $order_sql['sql'];

			if ( $include_wordpress_order_tiebreakers ) {
				$tiebreakers = $this->get_simple_wordpress_select_order_tiebreaker_sql( $tokens, $context );
				if ( ! empty( $tiebreakers ) ) {
					$sql .= ', ' . implode( ', ', $tiebreakers );
				}
			}
		}

		if ( null !== $context['limit_position'] ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql(
				$tokens,
				$context['limit_position'],
				$context['statement_end']
			);
		}
		return $sql;
	}
	private function get_simple_wordpress_select_order_tiebreaker_sql( array $tokens, array $context ): array {
		$tiebreakers = array();
		$scope       = $this->get_mysql_single_table_scope( $context['table_name'], $context['table_alias'] );
		$order_items = $this->parse_mysql_select_order_by_items(
			$tokens,
			$context['order_position'] + 2,
			$context['select_end'],
			array(),
			$scope
		);
		if ( null === $order_items ) {
			return $tiebreakers;
		}

		$tiebreaker_sql = $this->get_wordpress_posts_order_id_tiebreaker_sql( $tokens, $order_items, $scope, false );
		if ( null !== $tiebreaker_sql ) {
			$tiebreakers[] = $tiebreaker_sql;
		}

		$tiebreaker_sql = $this->get_simple_wordpress_approved_comments_order_tiebreaker_sql(
			$tokens,
			$context['table_name'],
			$context['where_position'],
			$context['where_end'],
			$order_items
		);
		if ( null !== $tiebreaker_sql ) {
			$tiebreakers[] = $tiebreaker_sql;
		}
		return $tiebreakers;
	}
	private function translate_direct_information_schema_cte_select_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::WITH_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$position = 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::RECURSIVE_SYMBOL === $tokens[ $position ]->id ) {
			return null;
		}

		$replacements = array();
		$cte_sources  = array();
		while ( $position < $statement_end ) {
			$cte = $this->parse_direct_information_schema_cte_select_definition( $query, $tokens, $position, $statement_end );
			if ( null === $cte ) {
				return null;
			}

			$name                               = $cte['name'];
			$columns                            = $cte['columns'];
			$replacements                       = array_merge( $replacements, $cte['replacements'] );
			$cte_sources[ strtolower( $name ) ] = compact( 'name', 'columns' );
			$position                           = $cte['position'];
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			break;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		if ( $this->select_references_direct_information_schema_relation( $tokens, $position + 1, $statement_end ) || ( 0 === strcasecmp( $this->db_name, 'information_schema' ) && $this->information_schema_cte_final_select_has_non_cte_table_reference( $tokens, $position, $statement_end, $cte_sources ) ) ) {
			$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $position, $statement_end );
			if ( '' === $select_query ) {
				return null;
			}

			$translated_select = $this->translate_direct_information_schema_select_query( $select_query, $cte_sources );
			if ( null === $translated_select ) {
				return null;
			}

			$replacements[] = $this->get_direct_information_schema_replacement( $position, $statement_end, $translated_select );
		}

		$this->sort_mysql_replacements( $replacements );
		return $this->translate_mysql_token_sequence_with_replacements_to_postgresql( $tokens, 0, $statement_end, $replacements );
	}
	private function parse_direct_information_schema_cte_select_definition( string $query, array $tokens, int $position, int $statement_end ): ?array {
		$cte_name_position = $position;
		$cte_name          = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $cte_name ) {
			return null;
		}

		$replacements                = array( $this->get_direct_information_schema_replacement( $cte_name_position, $cte_name_position + 1, $this->connection->quote_identifier( $cte_name ) ) );
		$column_list_insert_position = ++$position;
		$columns                     = null;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$column_list = $this->parse_direct_information_schema_cte_column_list( $tokens, $position, $statement_end );
			if ( null === $column_list ) {
				return null;
			}
			$columns  = $column_list['columns'];
			$position = $column_list['position'];
		}

		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::AS_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_select_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $statement_end );
		$select_start       = $position + 2;
		$select_end         = null === $after_select_close ? null : $after_select_close - 1;
		if ( null === $select_end || ! isset( $tokens[ $select_start ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $select_start ]->id ) {
			return null;
		}

		$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $select_start, $select_end );
		if ( '' === $select_query ) {
			return null;
		}

		$translated_select = $this->translate_direct_or_nested_information_schema_select_query( $select_query );
		if ( null === $translated_select ) {
			return null;
		}

		if ( null === $columns ) {
			$select_tokens        = $this->get_mysql_tokens( $select_query );
			$select_statement_end = $this->get_mysql_statement_end_position( $select_tokens, 1 );
			if ( null === $select_statement_end ) {
				return null;
			}

			$columns = $this->get_direct_information_schema_select_or_union_output_columns( $select_query, $select_tokens, $select_statement_end, true );
			if ( empty( $columns ) ) {
				return null;
			}
			$replacements[] = $this->get_direct_information_schema_replacement( $column_list_insert_position, $column_list_insert_position, '(' . implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ) . ')' );
		}

		$name           = $cte_name;
		$position       = $after_select_close;
		$replacements[] = $this->get_direct_information_schema_replacement( $select_start, $select_end, $translated_select );
		return compact( 'name', 'columns', 'position', 'replacements' );
	}
	private function get_direct_information_schema_replacement( int $start, int $end, string $sql ): array {
		return compact( 'start', 'end', 'sql' );
	}
	private function translate_direct_or_nested_information_schema_select_query( string $query ): ?string {
		$translated_select = $this->translate_direct_information_schema_select_query( $query );
		return null === $translated_select ? $this->translate_application_select_with_direct_information_schema_nested_selects( $query ) : $translated_select;
	}
	private function parse_direct_information_schema_cte_column_list( array $tokens, int $position, int $statement_end ): ?array {
		$after_column_list = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $statement_end );
		if ( null === $after_column_list ) {
			return null;
		}

		$column_ranges = $this->split_top_level_mysql_arguments( $tokens, $position + 1, $after_column_list - 1 );
		if ( null === $column_ranges || array() === $column_ranges ) {
			return null;
		}

		$columns = array();
		$seen    = array();
		foreach ( $column_ranges as $range ) {
			if ( $range['start'] + 1 !== $range['end'] || ! isset( $tokens[ $range['start'] ] ) ) {
				return null;
			}

			$column     = $this->get_direct_information_schema_identifier_token_value( $tokens[ $range['start'] ] );
			$column_key = null === $column ? null : strtolower( $column );
			if ( null === $column_key || isset( $seen[ $column_key ] ) ) {
				return null;
			}

			$seen[ $column_key ] = true;
			$columns[]           = $column;
		}
		$position = $after_column_list;
		return compact( 'columns', 'position' );
	}
	private function information_schema_cte_final_select_has_non_cte_table_reference( array $tokens, int $start, int $end, array $cte_sources ): bool {
		$position = $start;
		while ( $position < $end ) {
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
				return true;
			}

			$segment_end   = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::UNION_SYMBOL, $position + 1, $end ) ?? $end;
			$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $position + 1, $segment_end );
			if ( null !== $from_position && $this->information_schema_cte_source_range_has_non_cte_table_reference( $tokens, $from_position + 1, $this->find_direct_information_schema_source_end( $tokens, $from_position + 1, $segment_end ), $cte_sources ) ) {
				return true;
			}

			if ( $segment_end >= $end ) {
				return false;
			}

			$position = $segment_end + 1;
			if ( isset( $tokens[ $position ] ) && in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::ALL_SYMBOL, WP_MySQL_Lexer::DISTINCT_SYMBOL ), true ) ) {
				++$position;
			}
		}
		return false;
	}
	private function information_schema_cte_source_range_has_non_cte_table_reference( array $tokens, int $position, int $source_end, array $cte_sources ): bool {
		while ( $position < $source_end ) {
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				return true;
			}

			$identifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] );
			if ( null === $identifier ) {
				++$position;
				continue;
			}

			if ( ! isset( $cte_sources[ strtolower( $identifier ) ] ) ) {
				return true;
			}

			++$position;
			while ( $position < $source_end ) {
				$token_id = $tokens[ $position ]->id ?? null;
				if ( WP_MySQL_Lexer::COMMA_SYMBOL === $token_id || WP_MySQL_Lexer::JOIN_SYMBOL === $token_id ) {
					++$position;
					break;
				}

				if ( in_array( $token_id, array( WP_MySQL_Lexer::INNER_SYMBOL, WP_MySQL_Lexer::CROSS_SYMBOL, WP_MySQL_Lexer::LEFT_SYMBOL, WP_MySQL_Lexer::RIGHT_SYMBOL ), true ) ) {
					while ( $position < $source_end && WP_MySQL_Lexer::JOIN_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
						++$position;
					}
					if ( $position < $source_end ) {
						++$position;
					}
					break;
				}

				++$position;
			}
		}
		return false;
	}
	private function translate_direct_information_schema_select_query( string $query, array $cte_sources = array() ): ?string {
		$select = $this->get_mysql_top_level_select_parts( $query );
		if ( null === $select ) {
			return null;
		}

		$tokens        = $select['tokens'];
		$statement_end = $select['statement_end'];
		if ( $this->contains_top_level_mysql_token( $tokens, 1, $statement_end, array( WP_MySQL_Lexer::UNION_SYMBOL ) ) ) {
			return $this->translate_direct_information_schema_union_select_query( $query, $tokens, $statement_end );
		}

		$projection_start = 1;
		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $projection_start ]->id ) {
			++$projection_start;
		}

		$context = $this->get_direct_information_schema_select_context( $query, $tokens, $statement_end, $cte_sources );
		if ( null === $context ) {
			return $this->translate_direct_information_schema_no_from_select_query( $query, $tokens, $statement_end );
		}

		$nested_select_replacements = $this->get_direct_information_schema_range_replacements(
			$query,
			$tokens,
			1,
			$statement_end,
			null,
			array(
				'nested_select_ranges'  => array_merge(
					array(
						array(
							'start' => $projection_start,
							'end'   => $context['from_position'],
						),
					),
					$context['clause_ranges']
				),
				'cover_nested_selects'  => true,
				'coverage_replacements' => $context['source_replacements'],
			)
		);
		if ( null === $nested_select_replacements ) {
			return null;
		}

		$replacements = $this->get_direct_information_schema_projection_replacements( $tokens, $projection_start, $context['from_position'], $context, $nested_select_replacements );
		if ( null === $replacements ) {
			return null;
		}

		$replacements = $this->get_direct_information_schema_range_replacements(
			null,
			$tokens,
			1,
			$statement_end,
			$context,
			array(
				'replacements'                => array_merge( $replacements, $context['join_predicate_replacements'], $nested_select_replacements ),
				'protected_ranges'            => $nested_select_replacements,
				'expression_ranges'           => array_merge( $context['join_predicate_ranges'], $context['clause_ranges'] ),
				'include_binary_operators'    => true,
				'include_source_replacements' => true,
			)
		);
		if ( null === $replacements ) {
			return null;
		}
		return 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			1,
			$statement_end,
			$replacements
		);
	}
	private function get_direct_information_schema_projection_replacements( array $tokens, int $start, int $end, array $context, array $protected_ranges ): ?array {
		$descriptors = $this->get_direct_information_schema_projection_item_descriptors( $tokens, $start, $end, $context );
		if ( null === $descriptors ) {
			return null;
		}

		$replacements = array();
		foreach ( $descriptors as $descriptor ) {
			if ( null !== $descriptor['replacement_sql'] ) {
				$replacements[] = $this->get_direct_information_schema_replacement( $descriptor['expression_start'], $descriptor['expression_end'], $descriptor['replacement_sql'] );
				continue;
			}

			$expression_replacements = $this->get_direct_information_schema_range_replacements(
				null,
				$tokens,
				$descriptor['expression_start'],
				$descriptor['expression_end'],
				$context,
				array(
					'protected_ranges' => $protected_ranges,
				)
			);
			if ( null === $expression_replacements ) {
				return null;
			}

			$replacements = array_merge( $replacements, $expression_replacements );
		}
		return $replacements;
	}
	private function get_direct_information_schema_projection_item_descriptors( array $tokens, int $start, int $end, array $context ): ?array {
		$ranges      = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		$descriptors = array();
		foreach ( $ranges ?? array() as $range ) {
			$descriptors[] = $this->get_direct_information_schema_projection_item_descriptor( $tokens, $range, $context );
		}
		return null === $ranges || array() === $ranges || in_array( null, $descriptors, true ) ? null : $descriptors;
	}
	private function get_direct_information_schema_projection_item_descriptor( array $tokens, array $range, array $context ): ?array {
		$expression_bounds = $this->get_mysql_select_projection_expression_bounds( $tokens, $range['start'], $range['end'] );
		if ( null === $expression_bounds ) {
			return null;
		}

		$expression_start = $expression_bounds['start'];
		$expression_end   = $expression_bounds['end'];
		$as_position      = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $range['start'], $range['end'] );
		$alias            = null === $as_position
			? $this->get_mysql_implicit_projection_alias( $tokens, $range['start'], $range['end'] )
			: $this->get_mysql_projection_alias_token_value( $tokens[ $as_position + 1 ] ?? null );
		$star_sources     = $this->get_direct_information_schema_star_projection_sources(
			$tokens,
			$expression_start,
			$expression_end,
			$context
		);
		$count_bounds     = $this->normalize_mysql_expression_bounds( $tokens, $expression_start, $expression_end );
		$count_star       = $count_bounds['start'] + 4 === $count_bounds['end']
			&& isset( $tokens[ $count_bounds['start'] ], $tokens[ $count_bounds['start'] + 1 ], $tokens[ $count_bounds['start'] + 2 ], $tokens[ $count_bounds['start'] + 3 ] )
			&& $this->is_mysql_token_value( $tokens[ $count_bounds['start'] ], 'count' )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $count_bounds['start'] + 1 ]->id
			&& '*' === $tokens[ $count_bounds['start'] + 2 ]->get_bytes()
			&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $count_bounds['start'] + 3 ]->id;
		$reference        = $this->get_direct_information_schema_column_reference_for_expression( $tokens, $expression_start, $expression_end, $context );

		$replacement_sql = null;
		if ( null !== $star_sources ) {
			$replacement_sql = $this->get_direct_information_schema_star_projection_sql( $star_sources );
		} elseif ( $range['start'] === $expression_start && $range['end'] === $expression_end && $count_star ) {
			$replacement_sql = 'COUNT(*) AS ' . $this->connection->quote_identifier( 'COUNT(*)' );
		} elseif (
			null !== $reference
			&& 0 === strcasecmp( $reference['column'], 'TABLE_ROWS' )
			&& isset( $reference['source']['view'] )
			&& 'tables' === $reference['source']['view']
			&& $this->direct_information_schema_select_groups_by_table_name_for_source( $tokens, $context, $reference['source'] )
		) {
			$replacement_sql = 'MAX(' . $reference['sql'] . ')';
		}
		return compact( 'alias', 'count_star', 'expression_end', 'expression_start', 'range', 'reference', 'replacement_sql', 'star_sources' );
	}
	private function direct_information_schema_select_groups_by_table_name_for_source( array $tokens, array $context, array $source ): bool {
		foreach ( $context['clause_ranges'] as $range ) {
			if (
				WP_MySQL_Lexer::GROUP_SYMBOL !== ( $tokens[ $range['start'] ]->id ?? null )
				|| WP_MySQL_Lexer::BY_SYMBOL !== ( $tokens[ $range['start'] + 1 ]->id ?? null )
			) {
				continue;
			}

			$group_items = $this->split_top_level_mysql_arguments( $tokens, $range['start'] + 2, $range['end'] );
			if ( null === $group_items ) {
				return false;
			}

			foreach ( $group_items as $group_item ) {
				$reference = $this->get_direct_information_schema_column_reference_for_expression( $tokens, $group_item['start'], $group_item['end'], $context );
				if (
					null !== $reference
					&& 0 === strcasecmp( $reference['column'], 'TABLE_NAME' )
					&& $this->direct_information_schema_column_sources_are_same( $reference['source'], $source )
				) {
					return true;
				}
			}
		}
		return false;
	}
	private function get_direct_information_schema_column_reference_for_expression( array $tokens, int $start, int $end, array $context ): ?array {
		$reference = $this->get_direct_information_schema_column_reference_data( $tokens, $start, $end, $context );
		if ( null === $reference ) {
			return null;
		}
		return array(
			'source'         => $reference['source'],
			'column'         => $reference['column'],
			'token_position' => $reference['token_position'],
			'sql'            => $this->get_direct_information_schema_qualified_column_sql( $reference['source'], $reference['column'] ),
		);
	}
	private function get_direct_information_schema_column_reference_data( array $tokens, int $start, int $end, array $context ): ?array {
		if ( $start + 1 === $end && isset( $tokens[ $start ] ) ) {
			$column = $this->get_direct_information_schema_unqualified_column_name( $tokens[ $start ], $context );
			$source = ! is_string( $column ) ? null : $this->get_direct_information_schema_unqualified_column_source( $column, $context );
			return null === $source ? null : array(
				'source'         => $source,
				'column'         => $column,
				'token_position' => $start,
			);
		}

		$shape = null;
		if ( $start + 3 === $end ) {
			$shape = $this->get_direct_information_schema_dotted_reference_shape( $tokens, $start, $end );
		} elseif ( $start + 5 === $end ) {
			$shape = $this->get_direct_information_schema_dotted_reference_shape( $tokens, $start, $end, true );
		}
		return null === $shape ? null : $this->get_direct_information_schema_column_reference_data_for_shape( $shape, $context );
	}
	private function get_direct_information_schema_unqualified_column_source( string $column, array $context ): ?array {
		$source = null;
		foreach ( $context['sources'] as $candidate_source ) {
			if ( ! isset( $candidate_source['column_map'][ strtolower( $column ) ] ) ) {
				continue;
			}
			if ( null !== $source ) {
				return null;
			}
			$source = $candidate_source;
		}
		return $source;
	}
	private function get_direct_information_schema_column_reference_data_for_shape( array $shape, array $context ): ?array {
		$source = $this->get_direct_information_schema_source_for_qualifier( $shape['qualifier'], $context );
		$column = null === $source ? null : ( $source['column_map'][ strtolower( $shape['member'] ) ] ?? null );
		return null === $source || null === $column
			? null
			: array(
				'source'         => $source,
				'column'         => $column,
				'token_position' => $shape['member_position'],
				'end'            => $shape['end'],
			);
	}
	private function get_direct_information_schema_dotted_reference_shape( array $tokens, int $position, int $end, bool $schema_prefixed = false, bool $allow_star = false ): ?array {
		$qualifier_position = $schema_prefixed ? $position + 2 : $position;
		$member_position    = $schema_prefixed ? $position + 4 : $position + 2;
		if (
			$member_position >= $end
			|| WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null )
			|| ( $schema_prefixed && WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $qualifier_position + 1 ]->id ?? null ) )
		) {
			return null;
		}

		$first = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first || ( $schema_prefixed && 0 !== strcasecmp( $first, 'information_schema' ) ) ) {
			return null;
		}

		$qualifier = $schema_prefixed ? $this->get_direct_information_schema_identifier_token_value( $tokens[ $qualifier_position ] ?? null ) : $first;
		$member    = $this->get_direct_information_schema_identifier_token_value( $tokens[ $member_position ] ?? null );
		if ( null === $member && $allow_star && '*' === ( isset( $tokens[ $member_position ] ) ? $tokens[ $member_position ]->get_bytes() : null ) ) {
			$member = '*';
		}
		if ( null === $qualifier || null === $member ) {
			return null;
		}

		return array(
			'qualifier'       => $qualifier,
			'member'          => $member,
			'member_position' => $member_position,
			'end'             => $member_position + 1,
		);
	}
	private function direct_information_schema_column_sources_are_same( array $left, array $right ): bool {
		return $left['source_start'] === $right['source_start']
			&& $left['source_end'] === $right['source_end']
			&& 0 === strcasecmp( $left['alias'], $right['alias'] );
	}
	private function translate_direct_information_schema_no_from_select_query( string $query, array $tokens, int $statement_end ): ?string {
		if (
			null !== $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::FROM_SYMBOL,
				1,
				$statement_end
			)
			|| ! $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, 0, $statement_end )
		) {
			return null;
		}

		$sql = $this->translate_direct_information_schema_range_to_postgresql(
			$query,
			$tokens,
			1,
			$statement_end,
			null,
			array(
				'nested_select_ranges'   => array(
					array(
						'start' => 1,
						'end'   => $statement_end,
					),
				),
				'require_nested_selects' => true,
				'cover_nested_selects'   => true,
			)
		);
		return null === $sql ? null : 'SELECT ' . $sql;
	}
	private function get_direct_information_schema_range_replacements( ?string $query, array $tokens, int $start, int $end, ?array $context = null, array $options = array() ): ?array {
		$replacements     = $options['replacements'] ?? array();
		$protected_ranges = $options['protected_ranges'] ?? array();
		if ( isset( $options['nested_select_ranges'] ) ) {
			$has_nested_select = $this->contains_mysql_token( $tokens, $start, $end, array( WP_MySQL_Lexer::SELECT_SYMBOL ) );
			if ( empty( $options['nested_selects_if_present'] ) || $has_nested_select ) {
				if (
					null === $query
					|| (
						! empty( $options['reject_nested_select_unions'] )
						&& $this->contains_mysql_token( $tokens, $start, $end, array( WP_MySQL_Lexer::UNION_SYMBOL ) )
					)
				) {
					return null;
				}
				$nested_select_replacements = $this->get_information_schema_nested_select_replacements(
					$query,
					$tokens,
					$options['nested_select_ranges'],
					false
				);
				if (
					null === $nested_select_replacements
					|| ( ! empty( $options['require_nested_selects'] ) && array() === $nested_select_replacements )
				) {
					return null;
				}
				if (
					! empty( $options['cover_nested_selects'] )
					&& ! $this->direct_information_schema_nested_selects_are_covered(
						$tokens,
						$options['coverage_start'] ?? $start,
						$options['coverage_end'] ?? $end,
						array_merge( $options['coverage_replacements'] ?? array(), $replacements, $nested_select_replacements )
					)
				) {
					return null;
				}
				$replacements     = array_merge( $replacements, $nested_select_replacements );
				$protected_ranges = array_merge( $protected_ranges, $nested_select_replacements );
			}
		}

		if ( null !== $context ) {
			foreach (
				$options['expression_ranges'] ?? array(
					array(
						'start' => $start,
						'end'   => $end,
					),
				) as $range
			) {
				$current_database_function_replacements = $this->get_direct_information_schema_current_database_function_replacements(
					$tokens,
					$range['start'],
					$range['end'],
					$protected_ranges
				);
				if ( null === $current_database_function_replacements ) {
					return null;
				}
				$column_replacements = $this->get_direct_information_schema_column_replacements(
					$tokens,
					$range['start'],
					$range['end'],
					$context,
					array_merge( $protected_ranges, $current_database_function_replacements )
				);
				if ( null === $column_replacements ) {
					return null;
				}
				$range_replacements = array_merge( $current_database_function_replacements, $column_replacements );
				if ( ! empty( $options['include_binary_operators'] ) ) {
					$range_replacements = array_merge(
						$range_replacements,
						$this->get_direct_information_schema_binary_operator_replacements(
							$tokens,
							$range['start'],
							$range['end'],
							array_merge( $protected_ranges, $range_replacements )
						)
					);
				}
				$replacements = array_merge( $replacements, $range_replacements );
			}
		}

		if ( ! empty( $options['include_source_replacements'] ) ) {
			if ( null === $context || ! isset( $context['source_replacements'] ) ) {
				return null;
			}
			$replacements = array_merge( $replacements, $context['source_replacements'] );
		}

		$this->sort_mysql_replacements( $replacements );
		return $replacements;
	}
	private function translate_direct_information_schema_range_to_postgresql( ?string $query, array $tokens, int $start, int $end, ?array $context = null, array $options = array() ): ?string {
		$replacements = $this->get_direct_information_schema_range_replacements( $query, $tokens, $start, $end, $context, $options );
		return null === $replacements ? null : $this->translate_mysql_token_sequence_with_replacements_to_postgresql( $tokens, $start, $end, $replacements );
	}
	private function translate_application_select_with_direct_information_schema_nested_selects( string $query ): ?string {
		$select = $this->get_mysql_top_level_select_parts( $query );
		if ( null === $select ) {
			return null;
		}

		$tokens        = $select['tokens'];
		$statement_end = $select['statement_end'];
		if ( ! $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, 0, $statement_end ) ) {
			return null;
		}

		$context = $this->get_simple_mysql_single_table_select_context(
			$tokens,
			$statement_end,
			true,
			true
		);
		if ( null === $context || null === $context['where_position'] ) {
			return null;
		}

		$replacements = $this->get_direct_information_schema_range_replacements(
			$query,
			$tokens,
			1,
			$statement_end,
			null,
			array(
				'nested_select_ranges'   => array(
					array(
						'start' => $context['where_position'] + 1,
						'end'   => $context['where_end'],
					),
				),
				'require_nested_selects' => true,
				'cover_nested_selects'   => true,
			)
		);
		if (
			null === $replacements
			|| ! $this->is_supported_simple_mysql_expression_fragment_with_replacements(
				$tokens,
				$context['where_position'] + 1,
				$context['where_end'],
				$replacements
			)
		) {
			return null;
		}

		for ( $reference_position = 1; $reference_position + 2 < $statement_end; $reference_position++ ) {
			$shape = $this->get_direct_information_schema_dotted_reference_shape( $tokens, $reference_position, $statement_end );
			if ( null === $shape || 0 !== strcasecmp( $shape['qualifier'], 'information_schema' ) ) {
				continue;
			}

			$replacement_end = $this->get_covering_mysql_replacement_range_end( $reference_position, $replacements );
			if ( null === $replacement_end || $reference_position + 2 >= $replacement_end ) {
				return null;
			}
		}
		return $this->build_simple_mysql_single_table_select_sql( $tokens, $context, $replacements, false );
	}
	private function translate_direct_information_schema_union_select_query( string $query, array $tokens, int $statement_end ): ?string {
		$union = $this->parse_direct_information_schema_union_select_segments( $query, $tokens, $statement_end, true );
		if ( null === $union ) {
			return null;
		}

		$segments = array();
		foreach ( $union['segments'] as $select_query ) {
			$translated_select = $this->translate_direct_or_nested_information_schema_select_query( $select_query );
			if ( null === $translated_select ) {
				return null;
			}
			$segments[] = $translated_select;
		}

		$sql = $segments[0];
		foreach ( $union['operators'] as $index => $operator ) {
			$sql .= ' ' . $operator . ' ' . $segments[ $index + 1 ];
		}

		if ( $union['tail_start'] < $statement_end ) {
			$columns = $this->get_direct_information_schema_union_select_output_columns( $query, $tokens, $union['tail_start'] );
			if ( null === $columns || array() === $columns ) {
				return null;
			}

			$tail_sql = $this->translate_direct_information_schema_union_tail_to_postgresql(
				$tokens,
				$union['tail_start'],
				$statement_end,
				$columns
			);
			if ( null === $tail_sql ) {
				return null;
			}

			$sql .= $tail_sql;
		}
		return $sql;
	}
	private function parse_direct_information_schema_union_select_segments( string $query, array $tokens, int $statement_end, bool $allow_tail = false ): ?array {
		$segments   = array();
		$operators  = array();
		$position   = 0;
		$tail_start = $statement_end;

		while ( $position < $statement_end ) {
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}

			$union_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::UNION_SYMBOL, $position + 1, $statement_end );
			$select_end     = $union_position ?? $statement_end;
			if ( $allow_tail && null === $union_position ) {
				foreach ( array( WP_MySQL_Lexer::ORDER_SYMBOL, WP_MySQL_Lexer::LIMIT_SYMBOL ) as $token_id ) {
					$tail_position = $this->find_top_level_mysql_token( $tokens, $token_id, $position + 1, $statement_end );
					if ( null !== $tail_position ) {
						$select_end = min( $select_end, $tail_position );
					}
				}
				$tail_start = $select_end;
			}
			if ( $this->contains_top_level_mysql_token( $tokens, $position + 1, $select_end, array( WP_MySQL_Lexer::LIMIT_SYMBOL, WP_MySQL_Lexer::ORDER_SYMBOL ) ) ) {
				return null;
			}

			$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $position, $select_end );
			if ( '' === $select_query ) {
				return null;
			}
			$segments[] = $select_query;
			if ( null === $union_position ) {
				break;
			}

			$operator_position = $union_position + 1;
			if ( ! isset( $tokens[ $operator_position ] ) ) {
				return null;
			}

			$operators[] = WP_MySQL_Lexer::ALL_SYMBOL === $tokens[ $operator_position ]->id ? 'UNION ALL' : 'UNION';
			$position    = in_array( $tokens[ $operator_position ]->id, array( WP_MySQL_Lexer::ALL_SYMBOL, WP_MySQL_Lexer::DISTINCT_SYMBOL ), true ) ? $operator_position + 1 : $operator_position;
		}
		return count( $segments ) < 2 || count( $operators ) + 1 !== count( $segments ) ? null : compact( 'segments', 'operators', 'tail_start' );
	}
	private function translate_direct_information_schema_union_tail_to_postgresql( array $tokens, int $start, int $end, array $columns ): ?string {
		$position = $start;
		$sql      = '';

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::ORDER_SYMBOL === $tokens[ $position ]->id ) {
			$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $position + 1, $end );
			$order_end      = $limit_position ?? $end;
			$order_sql      = $this->translate_direct_information_schema_union_order_by_clause_to_postgresql(
				$tokens,
				$position,
				$order_end,
				$columns
			);
			if ( null === $order_sql ) {
				return null;
			}

			$sql     .= $order_sql;
			$position = $order_end;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::LIMIT_SYMBOL === $tokens[ $position ]->id ) {
			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $position, $end, true );
			if ( null === $limit_sql ) {
				return null;
			}

			$sql     .= $limit_sql;
			$position = $end;
		}
		return $position === $end && '' !== $sql ? $sql : null;
	}
	private function translate_direct_information_schema_union_order_by_clause_to_postgresql( array $tokens, int $start, int $end, array $columns ): ?string {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| WP_MySQL_Lexer::BY_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
		) {
			return null;
		}

		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start + 2, $end );
		if ( null === $ranges || array() === $ranges ) {
			return null;
		}

		$column_lookup = array();
		foreach ( $columns as $column ) {
			$column_lookup[ strtolower( $column ) ] = $column;
		}

		$items = array();
		foreach ( $ranges as $range ) {
			$item_start = $range['start'];
			$item_end   = $range['end'];
			$direction  = '';
			if (
				$item_start < $item_end
				&& (
					WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $item_end - 1 ]->id ?? null )
					|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $item_end - 1 ]->id ?? null )
				)
			) {
				$direction = ' ' . strtoupper( $tokens[ $item_end - 1 ]->get_bytes() );
				--$item_end;
			}

			if ( $item_start >= $item_end ) {
				return null;
			}

			if (
				$item_start + 1 === $item_end
				&& isset( $tokens[ $item_start ] )
				&& $this->is_mysql_unsigned_integer_token( $tokens[ $item_start ] )
			) {
				$ordinal = (int) $tokens[ $item_start ]->get_value();
				if ( $ordinal < 1 || $ordinal > count( $columns ) ) {
					return null;
				}

				$items[] = $tokens[ $item_start ]->get_bytes() . $direction;
				continue;
			}

			if ( $item_start + 1 !== $item_end || ! isset( $tokens[ $item_start ] ) ) {
				return null;
			}

			$column = $this->get_direct_information_schema_identifier_token_value( $tokens[ $item_start ] );
			if ( null === $column ) {
				return null;
			}

			$column_key = strtolower( $column );
			if ( ! isset( $column_lookup[ $column_key ] ) ) {
				return null;
			}

			$items[] = $this->connection->quote_identifier( $column_lookup[ $column_key ] ) . $direction;
		}
		return empty( $items ) ? null : ' ORDER BY ' . implode( ', ', $items );
	}
	private function get_direct_information_schema_select_context( string $query, array $tokens, int $statement_end, array $cte_sources = array() ): ?array {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $statement_end );
		if ( null === $from_position || 1 === $from_position ) {
			return null;
		}

		$source_start = $from_position + 1;
		$source_end   = $this->find_direct_information_schema_source_end( $tokens, $source_start, $statement_end );
		if ( $source_start >= $source_end ) {
			return null;
		}

		$sources = $this->parse_direct_information_schema_select_sources( $query, $tokens, $source_start, $source_end, $cte_sources );
		if ( null === $sources ) {
			return null;
		}

		$clause_ranges = $this->get_mysql_select_tail_clause_ranges( $tokens, $source_end, $statement_end );
		return array(
			'sources'                     => $sources['sources'],
			'from_position'               => $from_position,
			'source_start'                => $source_start,
			'source_end'                  => $source_end,
			'source_replacements'         => $sources['source_replacements'],
			'join_predicate_ranges'       => $sources['join_predicate_ranges'],
			'join_predicate_replacements' => $sources['join_predicate_replacements'],
			'using_columns'               => $sources['using_columns'],
			'clause_ranges'               => $clause_ranges,
		);
	}
	private function get_mysql_select_tail_clause_ranges( array $tokens, int $start, int $statement_end ): array {
		$clause_ranges = array();
		$clause_starts = array();
		foreach ( self::MYSQL_DIRECT_INFORMATION_SCHEMA_SELECT_TAIL_CLAUSE_TOKENS as $token_id ) {
			$position = $this->find_top_level_mysql_token( $tokens, $token_id, $start, $statement_end );
			if ( is_int( $position ) ) {
				$clause_starts[] = $position;
			}
		}
		sort( $clause_starts );
		foreach ( $clause_starts as $index => $range_start ) {
			$clause_ranges[] = array(
				'start' => $range_start,
				'end'   => $clause_starts[ $index + 1 ] ?? $statement_end,
			);
		}
		return $clause_ranges;
	}
	private function find_direct_information_schema_source_end( array $tokens, int $start, int $statement_end ): int {
		return $this->find_first_top_level_mysql_token( $tokens, self::MYSQL_DIRECT_INFORMATION_SCHEMA_SOURCE_END_TOKENS, $start, $statement_end ) ?? $statement_end;
	}
	private function parse_direct_information_schema_select_sources( string $query, array $tokens, int $start, int $end, array $cte_sources = array() ): ?array {
		if (
			0 !== strcasecmp( $this->db_name, 'information_schema' )
			&& ! $this->direct_information_schema_source_range_references_information_schema( $tokens, $start, $end )
		) {
			return null;
		}

		$sources                     = array();
		$aliases                     = array();
		$source_replacements         = array();
		$join_predicate_ranges       = array();
		$join_predicate_replacements = array();
		$using_columns               = array();
		$has_direct_source           = false;
		$has_non_joinable_relation   = false;
		$main_table_count            = 0;
		$position                    = $start;

		while ( $position < $end ) {
			$source_start = $position;
			$source       = $this->parse_direct_information_schema_select_source( $query, $tokens, $position, $end, $cte_sources );
			$source       = null === $source ? null : $this->get_direct_information_schema_select_source_descriptor( $source, $source_start, $aliases );
			if ( null === $source ) {
				return null;
			}

			$sources[]                 = $source;
			$source_replacements[]     = $source['replacement'];
			$has_direct_source         = $has_direct_source || 'direct_relation' === $source['family'];
			$has_non_joinable_relation = $has_non_joinable_relation || ! empty( $source['non_joinable_relation'] );
			$main_table_count         += 'main_table' === $source['family'] ? 1 : 0;
			$position                  = $source['position'];
			if ( count( $sources ) > 6 ) {
				return null;
			}

			$separator = $this->find_next_direct_information_schema_source_separator( $tokens, $position, $end );
			if ( null !== $separator && 'comma' === $separator['type'] ) {
				if ( $position !== $separator['start'] ) {
					return null;
				}

				$position = $separator['source_start'];
				continue;
			}

			$predicate_end = null === $separator ? $end : $separator['start'];
			$predicate     = $this->get_direct_information_schema_join_predicate_range_data(
				$tokens,
				$position,
				$predicate_end,
				$sources,
				$using_columns
			);
			if ( null === $predicate ) {
				return null;
			}
			if ( isset( $predicate['range'] ) ) {
				$join_predicate_ranges[] = $predicate['range'];
			}
			if ( isset( $predicate['replacement'] ) ) {
				$join_predicate_replacements[] = $predicate['replacement'];
			}
			if ( isset( $predicate['using_columns'] ) ) {
				$using_columns = $this->merge_direct_information_schema_using_columns( $using_columns, $predicate['using_columns'] );
			}

			if ( null === $separator ) {
				$position = $end;
				break;
			}

			$position = $separator['source_start'];
		}

		if ( ! $has_direct_source || ( count( $sources ) > 1 && ( $has_non_joinable_relation || $main_table_count > 1 ) ) ) {
			return null;
		}
		return compact( 'sources', 'source_replacements', 'join_predicate_ranges', 'join_predicate_replacements', 'using_columns' );
	}
	private function get_direct_information_schema_select_source_descriptor( array $source, int $source_start, array &$aliases ): ?array {
		if ( ! isset( $source['alias'], $source['position'] ) ) {
			return null;
		}

		$alias_key = strtolower( $source['alias'] );
		if ( isset( $aliases[ $alias_key ] ) ) {
			return null;
		}

		$family  = isset( $source['cte'] ) ? 'cte' : ( isset( $source['table'] ) ? 'main_table' : ( isset( $source['relation_sql'] ) || isset( $source['view'] ) ? 'direct_relation' : null ) );
		$columns = $source['columns'] ?? ( isset( $source['view'] ) ? $this->get_direct_information_schema_relation_columns( $source['view'] ) : null );
		if ( null === $family || null === $columns ) {
			return null;
		}

		if ( 'cte' === $family ) {
			$replacement_sql = sprintf( '%s AS %s', $this->connection->quote_identifier( $source['cte'] ), $this->connection->quote_identifier( $source['alias'] ) );
		} elseif ( 'main_table' === $family ) {
			$replacement_sql = $this->get_postgresql_dml_table_reference_sql( $source['table'], $source['alias'] );
		} else {
			$source['relation_sql'] = $source['relation_sql'] ?? $this->get_direct_information_schema_relation_sql( $source['view'] ?? '' );
			if ( null === $source['relation_sql'] ) {
				return null;
			}
			$replacement_sql = sprintf( '(%s) AS %s', $source['relation_sql'], $this->connection->quote_identifier( $source['alias'] ) );
		}

		$source['family']                = $family;
		$source['columns']               = $columns;
		$source['column_map']            = array();
		$source['source_start']          = $source_start;
		$source['source_end']            = $source['position'];
		$source['replacement']           = $this->get_direct_information_schema_replacement( $source['source_start'], $source['source_end'], $replacement_sql );
		$source['non_joinable_relation'] = isset( $source['view'] ) && false !== strpos( ' collation_character_set_applicability column_statistics columns_extensions files innodb_datafiles innodb_lock_waits innodb_tablespaces innodb_tablespaces_brief keywords optimizer_trace partitions profiling resource_groups schemata_extensions st_geometry_columns table_constraints_extensions tablespaces_extensions user_attributes view_routine_usage view_table_usage ', ' ' . strtolower( $source['view'] ) . ' ' );
		$aliases[ $alias_key ]           = true;
		foreach ( $columns as $column ) {
			$source['column_map'][ strtolower( $column ) ] = $column;
		}
		return $source;
	}
	private function parse_direct_information_schema_select_source( string $query, array $tokens, int $position, int $end, array $cte_sources = array() ): ?array {
		if ( isset( $tokens[ $position ], $tokens[ $position + 1 ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			return $this->parse_direct_information_schema_derived_select_source( $query, $tokens, $position, $end );
		}

		$source_start = $position;
		$first        = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first ) {
			return null;
		}

		if ( isset( $cte_sources[ strtolower( $first ) ] ) ) {
			$cte_source = $cte_sources[ strtolower( $first ) ];
			if ( ! isset( $cte_source['name'], $cte_source['columns'] ) || ! is_array( $cte_source['columns'] ) ) {
				return null;
			}

			$cte     = (string) $cte_source['name'];
			$columns = $cte_source['columns'];
			++$position;
			return $this->get_direct_information_schema_aliased_select_source( compact( 'cte', 'columns' ), $tokens, $position, $end, $cte );
		}

		++$position;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position ]->id
		) {
			if ( 0 !== strcasecmp( $first, 'information_schema' ) ) {
				if (
					0 === strcasecmp( $first, $this->main_db_name )
					|| 0 === strcasecmp( $first, 'public' )
				) {
					return $this->parse_direct_information_schema_main_table_source( $tokens, $source_start, $end );
				}
				return null;
			}

			$view = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position + 1 ] );
			if ( null === $view ) {
				return null;
			}
			$position += 2;
		} else {
			if ( 0 !== strcasecmp( $this->db_name, 'information_schema' ) ) {
				return $this->parse_direct_information_schema_main_table_source( $tokens, $source_start, $end );
			}

			$view = $first;
		}

		$view = strtolower( $view );
		return $this->get_direct_information_schema_aliased_select_source( array( 'view' => $view ), $tokens, $position, $end, $view );
	}
	private function parse_direct_information_schema_main_table_source( array $tokens, int $position, int $end ): ?array {
		$reference = $this->parse_mysql_table_reference( $tokens, $position, $end );
		if (
			null === $reference
			|| (
				0 !== strcasecmp( $reference['schema'], $this->main_db_name )
				&& 0 !== strcasecmp( $reference['schema'], 'public' )
			)
		) {
			return null;
		}

		$columns = array();
		foreach ( $this->get_mysql_dml_column_metadata( $reference['table'] ) as $column ) {
			if ( ! isset( $column['column_name'] ) ) {
				return null;
			}
			$columns[] = (string) $column['column_name'];
		}

		if ( empty( $columns ) ) {
			return null;
		}
		$table    = $reference['table'];
		$alias    = null === $reference['alias'] ? $table : $reference['alias'];
		$position = $reference['position'];
		return compact( 'table', 'alias', 'position', 'columns' );
	}
	private function parse_direct_information_schema_derived_select_source( string $query, array $tokens, int $position, int $end ): ?array {
		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
		if (
			null === $after_close
			|| ! isset( $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$select_start = $position + 1;
		$select_end   = $after_close - 1;
		$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $select_start, $select_end );
		if ( '' === $select_query ) {
			return null;
		}

		$translated_select = $this->translate_direct_information_schema_select_query( $select_query );
		if ( null === $translated_select ) {
			return null;
		}

		$select_tokens        = $this->get_mysql_tokens( $select_query );
		$select_statement_end = $this->get_mysql_statement_end_position( $select_tokens, 1 );
		if ( null === $select_statement_end ) {
			return null;
		}

		$columns = $this->get_direct_information_schema_select_or_union_output_columns( $select_query, $select_tokens, $select_statement_end );
		if ( null === $columns || array() === $columns ) {
			return null;
		}

		$position     = $after_close;
		$relation_sql = $translated_select;
		return $this->get_direct_information_schema_aliased_select_source( compact( 'relation_sql', 'columns' ), $tokens, $position, $end, 'derived' );
	}
	private function get_direct_information_schema_aliased_select_source( array $source, array $tokens, int &$position, int $end, string $default_alias ): ?array {
		$alias = $this->parse_direct_information_schema_optional_alias( $tokens, $position, $end, $default_alias );
		if ( null === $alias ) {
			return null;
		}
		$source['alias']    = $alias;
		$source['position'] = $position;
		return $source;
	}
	private function parse_direct_information_schema_optional_alias( array $tokens, int &$position, int $end, string $default_alias ): ?string {
		$explicit = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
			$explicit = true;
			++$position;
		}

		$alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $alias ) {
			return $explicit ? null : $default_alias;
		}
		++$position;
		return $alias;
	}
	private function get_direct_information_schema_select_or_union_output_columns( string $query, array $tokens, int $statement_end, bool $preserve_token_names = false ): ?array {
		if ( ! $this->contains_top_level_mysql_token( $tokens, 1, $statement_end, array( WP_MySQL_Lexer::UNION_SYMBOL ) ) ) {
			$context = $this->get_direct_information_schema_select_context( $query, $tokens, $statement_end );
			return null === $context ? null : $this->get_direct_information_schema_projection_output_columns( $tokens, $context, $preserve_token_names );
		}
		return $this->get_direct_information_schema_union_select_output_columns( $query, $tokens, $statement_end );
	}
	private function get_direct_information_schema_union_select_output_columns( string $query, array $tokens, int $statement_end ): ?array {
		$union = $this->parse_direct_information_schema_union_select_segments( $query, $tokens, $statement_end );
		if ( null === $union ) {
			return null;
		}

		$columns = null;
		foreach ( $union['segments'] as $select_query ) {
			$select_tokens        = $this->get_mysql_tokens( $select_query );
			$select_statement_end = $this->get_mysql_statement_end_position( $select_tokens, 1 );
			if ( null === $select_statement_end ) {
				return null;
			}

			$context = $this->get_direct_information_schema_select_context( $select_query, $select_tokens, $select_statement_end );
			if ( null === $context ) {
				return null;
			}

			$branch_columns = $this->get_direct_information_schema_projection_output_columns( $select_tokens, $context );
			if ( null === $branch_columns || array() === $branch_columns ) {
				return null;
			}

			if ( null === $columns ) {
				$columns = $branch_columns;
			} elseif ( count( $columns ) !== count( $branch_columns ) ) {
				return null;
			}
		}
		return $columns;
	}
	private function get_direct_information_schema_projection_output_columns( array $tokens, array $context, bool $preserve_token_names = false ): ?array {
		$projection_start = 1;
		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $projection_start ]->id ) {
			++$projection_start;
		}

		$descriptors = $this->get_direct_information_schema_projection_item_descriptors( $tokens, $projection_start, $context['from_position'], $context );
		if ( null === $descriptors ) {
			return null;
		}

		$columns = array();
		foreach ( $descriptors as $descriptor ) {
			if ( null !== $descriptor['star_sources'] ) {
				if ( null !== $descriptor['alias'] ) {
					return null;
				}
				$columns = array_merge( $columns, ...array_column( $descriptor['star_sources'], 'columns' ) );
				continue;
			}

			$column = $descriptor['alias'] ?? ( $descriptor['count_star'] ? 'COUNT(*)' : null );
			if ( null === $column && null !== $descriptor['reference'] ) {
				$column = $preserve_token_names ? $this->get_direct_information_schema_identifier_token_value( $tokens[ $descriptor['reference']['token_position'] ] ) : $descriptor['reference']['column'];
			}
			if ( null === $column ) {
				return null;
			}
			$columns[] = $column;
		}
		return $columns;
	}
	private function get_direct_information_schema_star_projection_sql( array $sources ): string {
		$select_lists = array();
		foreach ( $sources as $source ) {
			$select = array();
			foreach ( $source['columns'] as $column ) {
				$select[] = $this->connection->quote_identifier( $source['alias'] ) . '.' . $this->connection->quote_identifier( $column ) . ' AS ' . $this->connection->quote_identifier( $column );
			}
			$select_lists[] = implode( ', ', $select );
		}
		return implode( ', ', $select_lists );
	}
	private function get_direct_information_schema_star_projection_sources( array $tokens, int $start, int $end, array $context ): ?array {
		if ( $start + 1 === $end && isset( $tokens[ $start ] ) && '*' === $tokens[ $start ]->get_bytes() ) {
			return $context['sources'];
		}

		$shape = null;
		if ( $start + 3 === $end ) {
			$shape = $this->get_direct_information_schema_dotted_reference_shape( $tokens, $start, $end, false, true );
		} elseif ( $start + 5 === $end ) {
			$shape = $this->get_direct_information_schema_dotted_reference_shape( $tokens, $start, $end, true, true );
		}
		if ( null === $shape || '*' !== $shape['member'] ) {
			return null;
		}

		$source = $this->get_direct_information_schema_source_for_qualifier( $shape['qualifier'], $context );
		return null === $source ? null : array( $source );
	}
	private function find_next_direct_information_schema_source_separator( array $tokens, int $start, int $end ): ?array {
		$depth = 0;
		for ( $position = $start; $position < $end; $position++ ) {
			$token_id = $tokens[ $position ]->id;
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $token_id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $token_id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::COMMA_SYMBOL === $token_id ) {
				return $this->get_direct_information_schema_source_separator( 'comma', $position, $position + 1 );
			}

			$source_start = null;
			if ( WP_MySQL_Lexer::JOIN_SYMBOL === $token_id ) {
				$source_start = $position + 1;
			} elseif (
				isset( $tokens[ $position + 1 ] )
				&& in_array( $token_id, array( WP_MySQL_Lexer::INNER_SYMBOL, WP_MySQL_Lexer::CROSS_SYMBOL ), true )
				&& WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$source_start = $position + 2;
			} elseif ( in_array( $token_id, array( WP_MySQL_Lexer::LEFT_SYMBOL, WP_MySQL_Lexer::RIGHT_SYMBOL ), true ) ) {
				$join_position = $position + 1;
				if ( isset( $tokens[ $join_position ] ) && WP_MySQL_Lexer::OUTER_SYMBOL === $tokens[ $join_position ]->id ) {
					++$join_position;
				}
				if ( isset( $tokens[ $join_position ] ) && WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $join_position ]->id ) {
					$source_start = $join_position + 1;
				}
			}

			if ( null !== $source_start ) {
				return $this->get_direct_information_schema_source_separator( 'join', $position, $source_start );
			}
		}
		return null;
	}
	private function get_direct_information_schema_source_separator( string $type, int $start, int $source_start ): array {
		return compact( 'type', 'start', 'source_start' );
	}
	private function get_direct_information_schema_join_predicate_range_data( array $tokens, int $start, int $end, array $sources, array $using_columns ): ?array {
		if ( $start === $end ) {
			return array();
		}

		$token_id = $tokens[ $start ]->id ?? null;
		if ( in_array( $token_id, array( WP_MySQL_Lexer::USING_SYMBOL, WP_MySQL_Lexer::ON_SYMBOL ), true ) ) {
			$using = $this->get_direct_information_schema_join_using_replacement( $tokens, $start, $end, $sources, $using_columns );
			if ( null !== $using ) {
				return $using;
			}
			if ( WP_MySQL_Lexer::USING_SYMBOL === $token_id ) {
				return null;
			}
		}

		if ( WP_MySQL_Lexer::ON_SYMBOL !== $token_id ) {
			return null;
		}

		if ( $this->contains_mysql_token(
			$tokens,
			$start + 1,
			$end,
			array(
				WP_MySQL_Lexer::SELECT_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
			)
		) ) {
			return null;
		}
		return array(
			'range' => array(
				'start' => $start,
				'end'   => $end,
			),
		);
	}
	private function get_direct_information_schema_join_using_replacement( array $tokens, int $start, int $end, array $sources, array $using_columns ): ?array {
		if ( count( $sources ) < 2 ) {
			return null;
		}

		$descriptor = $this->get_direct_information_schema_join_using_descriptor( $tokens, $start, $end, $sources );
		if ( null === $descriptor ) {
			return null;
		}
		$current_source = $sources[ count( $sources ) - 1 ];
		$columns        = array();
		$seen_columns   = array();
		$new_using      = array();

		foreach ( $descriptor['columns'] as $column ) {
			$column_key = strtolower( $column['column'] );
			if ( isset( $seen_columns[ $column_key ] ) ) {
				return null;
			}

			$aliases = $this->get_direct_information_schema_join_using_column_aliases(
				$column_key,
				$column['previous_sources'],
				$current_source,
				$using_columns,
				$descriptor['guard_ambiguous_previous']
			);
			if ( null === $aliases ) {
				return null;
			}

			$seen_columns[ $column_key ] = true;
			$new_using[ $column_key ]    = array(
				'column'  => $column['column'],
				'aliases' => $aliases,
			);
			$columns[]                   = $this->connection->quote_identifier( $column['column'] );
		}
		return $this->get_direct_information_schema_join_using_replacement_data( $start, $end, $columns, $new_using );
	}
	private function get_direct_information_schema_join_using_descriptor( array $tokens, int $start, int $end, array $sources ): ?array {
		$token_id                 = $tokens[ $start ]->id ?? null;
		$current_source           = $sources[ count( $sources ) - 1 ];
		$guard_ambiguous_previous = WP_MySQL_Lexer::USING_SYMBOL === $token_id;

		if ( $guard_ambiguous_previous ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null ) ) {
				return null;
			}

			$position         = $start + 2;
			$previous_sources = array_slice( $sources, 0, -1 );
			$columns          = array();
			while ( $position < $end && isset( $tokens[ $position ] ) ) {
				$current_column = $this->get_direct_information_schema_column_name_for_token( $tokens[ $position ], $current_source['column_map'] );
				if ( null === $current_column ) {
					return null;
				}

				$columns[] = array(
					'column'           => $current_column,
					'previous_sources' => $previous_sources,
				);
				++$position;

				if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
					++$position;
					continue;
				}

				if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
					++$position;
					return $position === $end ? compact( 'columns', 'guard_ambiguous_previous' ) : null;
				}
				return null;
			}
			return null;
		}

		if ( WP_MySQL_Lexer::ON_SYMBOL !== $token_id ) {
			return null;
		}

		$current_alias = strtolower( $current_source['alias'] );
		$position      = $start + 1;
		$columns       = array();
		while ( $position < $end ) {
			$left = $this->parse_direct_information_schema_qualified_column_reference( $tokens, $position, $end, $sources );
			if ( null === $left || ! isset( $tokens[ $left['end'] ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $left['end'] ]->id ) {
				return null;
			}

			$right = $this->parse_direct_information_schema_qualified_column_reference( $tokens, $left['end'] + 1, $end, $sources );
			if ( null === $right || 0 !== strcasecmp( $left['column'], $right['column'] ) ) {
				return null;
			}

			$left_alias  = strtolower( $left['source']['alias'] );
			$right_alias = strtolower( $right['source']['alias'] );
			if ( $left_alias === $current_alias && $right_alias !== $current_alias ) {
				$previous_source = $right['source'];
				$column          = $left['column'];
			} elseif ( $right_alias === $current_alias && $left_alias !== $current_alias ) {
				$previous_source = $left['source'];
				$column          = $right['column'];
			} else {
				return null;
			}

			$columns[] = array(
				'column'           => $column,
				'previous_sources' => array( $previous_source ),
			);
			$position  = $right['end'];

			if ( $position === $end ) {
				return compact( 'columns', 'guard_ambiguous_previous' );
			}

			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}
			++$position;
		}
		return null;
	}
	private function get_direct_information_schema_join_using_column_aliases( string $column_key, array $previous_sources, array $current_source, array $using_columns, bool $guard_ambiguous_previous ): ?array {
		$previous_matches = array();
		foreach ( $previous_sources as $source ) {
			if ( isset( $source['column_map'][ $column_key ] ) ) {
				$previous_matches[] = $source;
			}
		}

		if ( empty( $previous_matches ) ) {
			return null;
		}

		$matched_aliases = array();
		foreach ( $previous_matches as $source ) {
			$matched_aliases[ strtolower( $source['alias'] ) ] = true;
		}

		if ( $guard_ambiguous_previous && count( $previous_matches ) > 1 ) {
			$merged_aliases = $using_columns[ $column_key ]['aliases'] ?? array();
			foreach ( $matched_aliases as $alias => $_ ) {
				if ( ! isset( $merged_aliases[ $alias ] ) ) {
					return null;
				}
			}
		}

		$matched_aliases[ strtolower( $current_source['alias'] ) ] = true;
		if ( isset( $using_columns[ $column_key ]['aliases'] ) ) {
			$matched_aliases = array_merge( $using_columns[ $column_key ]['aliases'], $matched_aliases );
		}

		return $matched_aliases;
	}
	private function get_direct_information_schema_join_using_replacement_data( int $start, int $end, array $columns, array $using_columns ): ?array {
		return empty( $columns ) ? null : array(
			'replacement'   => $this->get_direct_information_schema_replacement( $start, $end, 'USING (' . implode( ', ', $columns ) . ')' ),
			'using_columns' => $using_columns,
		);
	}
	private function parse_direct_information_schema_qualified_column_reference( array $tokens, int $position, int $end, array $sources ): ?array {
		$shape = $this->get_direct_information_schema_dotted_reference_shape( $tokens, $position, $end );
		return null === $shape ? null : $this->get_direct_information_schema_column_reference_data_for_shape( $shape, array( 'sources' => $sources ) );
	}
	private function merge_direct_information_schema_using_columns( array $columns, array $new_columns ): array {
		foreach ( $new_columns as $key => $metadata ) {
			if ( isset( $columns[ $key ] ) ) {
				$metadata['aliases'] = array_merge( $columns[ $key ]['aliases'], $metadata['aliases'] );
			}
			$columns[ $key ] = $metadata;
		}
		return $columns;
	}
	private function direct_information_schema_source_range_references_information_schema( array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position + 1 < $end; $position++ ) {
			$shape = $this->get_direct_information_schema_dotted_reference_shape( $tokens, $position, $end );
			if ( null !== $shape && 0 === strcasecmp( $shape['qualifier'], 'information_schema' ) ) {
				return true;
			}

			$identifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null !== $identifier && 0 === strcasecmp( $identifier, 'information_schema' ) && WP_MySQL_Lexer::DOT_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null ) ) {
				return true;
			}
		}
		return false;
	}
	private function get_direct_information_schema_identifier_token_value( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		$identifier = $this->get_mysql_identifier_token_value( $token );
		if ( null !== $identifier ) {
			return $identifier;
		}

		if ( in_array( $token->id, self::MYSQL_DIRECT_INFORMATION_SCHEMA_IDENTIFIER_STOP_TOKENS, true ) ) {
			return null;
		}

		$value = $token->get_value();
		return 1 === preg_match( '/^[A-Za-z_][A-Za-z0-9_]*$/', $value ) ? $value : null;
	}
	private function get_direct_information_schema_relation_names(): array {
		$names = array_keys( $this->get_direct_information_schema_relation_column_map() );
		sort( $names, SORT_STRING );
		return $names;
	}
	private function get_direct_information_schema_relation_columns( string $view ): ?array {
		$columns = $this->get_direct_information_schema_relation_column_map();
		$view    = strtolower( $view );
		return isset( $columns[ $view ] ) ? explode( ' ', $columns[ $view ] ) : null;
	}
