		}

		if ( 'st_geometry_columns' === $view ) {
			$type_list = implode( ', ', array_map( array( $this->connection, 'quote' ), array_merge( array_keys( array_intersect( self::MYSQL_TEXT_DOMAIN_TYPES, self::MYSQL_SPATIAL_COLUMN_TYPES ) ), self::MYSQL_SPATIAL_COLUMN_TYPES ) ) );
			return $this->get_direct_information_schema_native_relation_sql( 'st_geometry_columns', $this->get_mysql_key_value_array( 'alias', 'c', 'from', 'information_schema.columns c', 'where', 'c.table_schema !~ ' . $this->connection->quote( '^(pg_|information_schema$|pg_catalog$)' ) . ' AND LOWER(COALESCE(c.domain_name, c.udt_name, c.data_type)) IN (' . $type_list . ')', 'expressions', 'SRS_NAME=NULL; SRS_ID=NULL; GEOMETRY_TYPE_NAME=UPPER(CASE WHEN c.domain_name LIKE ' . $this->connection->quote( '__wp_mysql_%' ) . ' THEN SUBSTR(c.domain_name, 12) ELSE COALESCE(c.udt_name, c.data_type) END)' ) );
