		}
		return null;
	}

	private function get_postgresql_visible_schema_condition_sql( string $schema_sql, ?string $relation_oid_sql = null ): string {
		$schema_condition = sprintf( '%1$s !~ %2$s', $schema_sql, $this->connection->quote( '^(pg_|information_schema$|pg_catalog$)' ) );
		if ( null === $relation_oid_sql ) {
			return $schema_condition;
		}

		return sprintf( '(%1$s OR (%2$s ~ %3$s AND %4$s IS NOT NULL AND pg_catalog.pg_table_is_visible(%4$s)))', $schema_condition, $schema_sql, $this->connection->quote( '^pg_temp_[0-9]+$' ), $relation_oid_sql );
	}

