			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null )
			|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== ( $tokens[ $position + 3 ]->id ?? null )
