		$column_key  = null === $column_name ? null : strtolower( $column_name );
		if ( null === $column_key || ! isset( $column_lookup[ $column_key ] ) ) {
			return null;
		}

		$lookup_value = $column_lookup[ $column_key ];
		return array(
			'column'       => is_string( $lookup_value ) ? $lookup_value : $column_name,
			'end'          => $position + 4,
			'lookup_value' => $lookup_value,
