	private function get_mysql_upsert_expression_replacement( int $start, int $end, string $sql ): array {
		return array(
			'start' => $start,
			'end'   => $end,
			'sql'   => $sql,
		);
	}
	private function contains_unsupported_mysql_convert_function_outside_replacements( array $tokens, int $start, int $end, array $replacements ): bool {
		return $this->contains_unsupported_mysql_function_outside_replacements( $tokens, $start, $end, $replacements, 'contains_unsupported_mysql_convert_function' );
	}
	private function contains_unsupported_mysql_common_function_outside_replacements( array $tokens, int $start, int $end, array $replacements ): bool {
		return $this->contains_unsupported_mysql_function_outside_replacements( $tokens, $start, $end, $replacements, 'contains_unsupported_mysql_common_function' );
	}
	private function contains_unsupported_mysql_function_outside_replacements( array $tokens, int $start, int $end, array $replacements, string $scanner_name ): bool {
		$segment_start = $start;
		foreach ( $replacements as $replacement ) {
			if (
				$segment_start < $replacement['start']
				&& $this->$scanner_name( $tokens, $segment_start, $replacement['start'] )
			) {
				return true;
			}

			$segment_start = max( $segment_start, $replacement['end'] );
		}
		return $segment_start < $end
			&& $this->$scanner_name( $tokens, $segment_start, $end );
	}
	private function translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql( array $tokens, int $start, int $end, array $replacements ): ?string {
