	private function get_postgresql_mysql_temporal_arithmetic_sql_with_replacements( array $tokens, array $bounds, array $replacements ): ?string {
		$expression_sql = $this->translate_mysql_upsert_expression_subrange_with_replacements_to_postgresql( $tokens, $bounds['expression_start'], $bounds['expression_end'], $replacements );
		if ( null === $expression_sql ) {
			return null;
		}

		$interval_sql = $bounds['interval_sql'] ?? null;
		if ( null === $interval_sql ) {
			$value_sql = $this->translate_mysql_upsert_expression_subrange_with_replacements_to_postgresql( $tokens, $bounds['interval_value_start'], $bounds['interval_value_end'], $replacements );
			if ( null === $value_sql ) {
				return null;
			}

			$interval_sql = $this->get_postgresql_mysql_interval_sql( $value_sql, $bounds['interval_unit'] );
		}
		return sprintf(
			'(%1$s %2$s %3$s)',
			$this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql ),
			$bounds['operator'],
			$interval_sql
