			: $this->translate_mysql_upsert_expression_subrange_with_replacements_to_postgresql( $tokens, $start, $end, $replacements );
	}
	private function get_mysql_common_function_bounds( array $tokens, int $position, int $end ): ?array {
		$function = $this->get_mysql_common_function_name( $tokens[ $position ] ?? null );
		if (
			null === $function
			|| ! isset( $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}
		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}
		return array(
			'function'        => $function,
			'arguments_start' => $position + 2,
			'arguments_end'   => $after_close - 1,
			'close'           => $after_close - 1,
		);
	}
	private function get_mysql_common_function_name( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}
		$keyword_functions = array_combine(
			array( WP_MySQL_Lexer::ASCII_SYMBOL, WP_MySQL_Lexer::COALESCE_SYMBOL, WP_MySQL_Lexer::CURRENT_USER_SYMBOL, WP_MySQL_Lexer::CURDATE_SYMBOL, WP_MySQL_Lexer::CURTIME_SYMBOL, WP_MySQL_Lexer::CURRENT_DATE_SYMBOL, WP_MySQL_Lexer::CURRENT_TIME_SYMBOL, WP_MySQL_Lexer::CURRENT_TIMESTAMP_SYMBOL, WP_MySQL_Lexer::DATABASE_SYMBOL, WP_MySQL_Lexer::DATE_SYMBOL, WP_MySQL_Lexer::IF_SYMBOL, WP_MySQL_Lexer::LEFT_SYMBOL, WP_MySQL_Lexer::MID_SYMBOL, WP_MySQL_Lexer::NOW_SYMBOL, WP_MySQL_Lexer::REPLACE_SYMBOL, WP_MySQL_Lexer::REGEXP_SYMBOL, WP_MySQL_Lexer::REPEAT_SYMBOL, WP_MySQL_Lexer::REVERSE_SYMBOL, WP_MySQL_Lexer::RIGHT_SYMBOL, WP_MySQL_Lexer::ROW_COUNT_SYMBOL, WP_MySQL_Lexer::SCHEMA_SYMBOL, WP_MySQL_Lexer::SUBSTR_SYMBOL, WP_MySQL_Lexer::SUBSTRING_SYMBOL, WP_MySQL_Lexer::TRIM_SYMBOL, WP_MySQL_Lexer::UTC_DATE_SYMBOL, WP_MySQL_Lexer::UTC_TIME_SYMBOL, WP_MySQL_Lexer::UTC_TIMESTAMP_SYMBOL ),
			explode( ' ', 'ascii coalesce current_user curdate utc_time curdate utc_time utc_timestamp database date if left substring now replace regexp repeat reverse right row_count database substring substring trim utc_date utc_time utc_timestamp' )
		);
		if ( isset( $keyword_functions[ $token->id ] ) ) {
			return $keyword_functions[ $token->id ];
		}
		if ( WP_MySQL_Lexer::USER_SYMBOL === $token->id ) {
			$name = strtolower( $token->get_value() );
			return in_array( $name, array( 'user', 'session_user', 'system_user' ), true ) ? $name : null;
		}
