			'json_valid'                                 => array( 1, 1, 'argument_method', 'get_postgresql_mysql_json_valid_sql' ),
			'length'                                     => array( 1, 1, 'argument_method', 'get_postgresql_mysql_text_byte_length_sql' ),
			'locate'                                     => array( 3, 3, 'argument_method', 'get_postgresql_mysql_locate_with_position_sql' ),
