			'database schema'                            => array( 0, 0, 'sql', $this->connection->quote( $this->db_name ) ),
			'found_rows'                                 => array( 0, 0, 'sql', (string) $this->last_found_rows ),
			'row_count'                                  => array( 0, 0, 'sql', (string) $this->last_row_count ),
			'uuid'                                       => array( 0, 0, 'sql', "LOWER(REGEXP_REPLACE(MD5(CAST(CLOCK_TIMESTAMP() AS text) || CAST(RANDOM() AS text) || CAST(PG_BACKEND_PID() AS text)), '^(.{8})(.{4}).(.{3}).(.{3})(.{12})$', '\\1-\\2-4\\3-8\\4-\\5'))" ),
