			&& $argument_count >= $minimum
			&& ( null === $maximum || $argument_count <= $maximum );
	}
	private function render_postgresql_mysql_common_function_sql_descriptor( string $function_name, array $argument_sql, array $descriptor ): ?string {
		switch ( $descriptor[2] ) {
			case 'template':
				return vsprintf( $descriptor[3], $argument_sql );
			case 'method':
				return $this->{$descriptor[3]}( $argument_sql );
			case 'argument_method':
				return $this->{$descriptor[3]}( ...$argument_sql );
			case 'sql':
				return $descriptor[3];
			case 'temporal_name':
				$expression_text_sql = sprintf( 'CAST(%s AS text)', $argument_sql[0] );
				$timestamp_sql       = $this->get_postgresql_zero_date_safe_timestamp_sql( $argument_sql[0] );
				$branches            = array();
				foreach ( $descriptor[4] as $value => $name ) {
					$branches[] = sprintf( 'WHEN %d THEN %s', $value, $this->connection->quote( $name ) );
				}
				return sprintf( 'CASE WHEN %1$s OR %2$s THEN NULL ELSE CASE CAST(EXTRACT(%3$s FROM %4$s) AS integer) %5$s END END', $this->get_postgresql_empty_temporal_condition_sql( $expression_text_sql ), $this->get_postgresql_zero_date_condition_sql( $expression_text_sql ), $descriptor[3], $timestamp_sql, implode( ' ', $branches ) );
			case 'variadic_template':
				return sprintf( $descriptor[3], implode( ', ', $argument_sql ) );
			case 'cast_join':
				return '(CAST(' . implode( ' AS text)' . $descriptor[3] . 'CAST(', $argument_sql ) . ' AS text))';
			case 'zero_date_extract':
				return $this->get_postgresql_zero_date_safe_extract_sql( $descriptor[3], $argument_sql[0] );
			case 'pad':
				return sprintf(
					'CASE WHEN %1$s IS NULL OR %2$s IS NULL OR %3$s IS NULL OR CAST(%2$s AS integer) < 0 OR CAST(%3$s AS text) = \'\' THEN NULL ELSE %4$s(CAST(%1$s AS text), CAST(%2$s AS integer), CAST(%3$s AS text)) END',
					$argument_sql[0],
					$argument_sql[1],
					$argument_sql[2],
					strtoupper( $function_name )
				);
			case 'null_sensitive_variadic':
				return sprintf( 'CASE WHEN %1$s IS NULL THEN NULL ELSE %2$s(%3$s) END', implode( ' IS NULL OR ', $argument_sql ), strtoupper( $function_name ), implode( ', ', $argument_sql ) );
			case 'ascii':
				$text_sql           = sprintf( 'CAST(%s AS text)', $argument_sql[0] );
				$prefix_chars       = preg_match_all( '/./us', self::MYSQL_TEXT_ENCODING_PREFIX );
				$prefix_length      = false === $prefix_chars ? strlen( self::MYSQL_TEXT_ENCODING_PREFIX ) : $prefix_chars;
				$prefix_sql         = $this->connection->get_pdo()->quote( self::MYSQL_TEXT_ENCODING_PREFIX );
				$payload_sql        = sprintf( 'SUBSTR(%s, %d)', $text_sql, $prefix_length + 1 );
