			WP_MySQL_Lexer::ADDDATE_SYMBOL  => '+1',
			WP_MySQL_Lexer::DATE_ADD_SYMBOL => '+0',
			WP_MySQL_Lexer::DATE_SUB_SYMBOL => '-0',
			WP_MySQL_Lexer::SUBDATE_SYMBOL  => '-1',
		);
		$descriptor  = $descriptors[ $tokens[ $position ]->id ] ?? null;
		if ( null === $descriptor ) {
			return null;
		}
		return array(
			'operator'                  => $descriptor[0],
			'permits_numeric_day_alias' => '1' === $descriptor[1],
